window.__SUM[19]={"LR000005":{"pair":"ADAM12 -> ITGB1","headline":"ADAM12 disintegrin domain binds integrin alpha9beta1, implicating the beta1 chain only as part of the complex.","interaction_type":"direct binding","direction_and_effect":"Recombinant ADAM-12 and ADAM-15 disintegrin domains bind integrin alpha9beta1 in an RGD-independent manner [PMID:10944520].","molecular_requirements":"Evidence is for the alpha9beta1 heterodimer; beta1 is its partner chain, and beta1 alone is not shown [PMID:10944520].","affinity_potency":[],"species_and_systems":"Recombinant domains; species not reported in our evidence.","localisation_and_range":"ADAM12 is flagged secreted; ITGB1 not secreted [flag].","caveats":"One abstract-only paper; ITGB1 is credited through alpha9beta1, so expression of ITGA9 is needed to follow this evidence.","key_references":[{"PMID":"10944520","why":"alpha9beta1 binding to ADAM-12 disintegrin domain"}],"covers":["LR000005","LR003555"]},"LR000014":{"pair":"ADAM23 -> ITGB3","headline":"ADAM23 binds alphavbeta3 via its disintegrin domain; human, two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"ADAM 23 shows a specific interaction with alphavbeta3 via its disintegrin loop [PMID:10749942]; knockdown enhances alphavbeta3 activation 2- to 4-fold and migration/adhesion [PMID:19549921].","molecular_requirements":"beta3 acts with alphav; RGD-independent loop sequence [PMID:10749942].","affinity_potency":[],"species_and_systems":"Human cells, transfected HeLa, MDA-MB-435 [PMID:10749942][PMID:19549921]. Mouse pair is ortholog-inferred.","localisation_and_range":"ADAM23 is flagged secreted [flag].","caveats":"Abstracts only; interaction modulatory effect annotated Stimulatory in the database but the 2009 paper shows ADAM23 dampens activation, which may conflict.","key_references":[{"PMID":"10749942","why":"Disintegrin loop binds alphavbeta3"},{"PMID":"19549921","why":"ADAM23 loss enhances alphavbeta3 activation"}],"covers":["LR000014","LR003564"]},"LR000023":{"pair":"ADAM9 -> ITGAV","headline":"ADAM9 disintegrin domain binds alphaV-containing integrins (alphaVbeta5 antibody-blocked adhesion); two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"GST-ADAM9 disintegrin domain recovered alphav and other integrin chains from renal lysate [PMID:15361064]. Myeloma cell adhesion to the recombinant disintegrin domain was completely blocked by anti-alpha(v)beta(5) but not antibodies to other subunits, and RGD peptides had no effect [PMID:11162558]. The curated effect is Stimulatory [flag].","molecular_requirements":"Partner is an alphaV heterodimer; beta5 is implicated by the antibody block [PMID:11162558], while the first paper also recovered beta1 [PMID:15361064]. Divalent cations (Mn2+, Ca2+) supported binding; RGD-independent [PMID:11162558].","affinity_potency":[],"species_and_systems":"Human; HEK-293/renal lysate [PMID:15361064] and myeloma cells with recombinant disintegrin domain [PMID:11162558]. Mouse pair is ortholog-inferred, not tested.","localisation_and_range":"Annotation flags mark ADAM9 as secreted [flag], but the papers use its disintegrin domain as a recombinant or cell-surface-expressed protein, so the physiologically relevant range (juxtacrine versus shed) is not settled in our evidence.","caveats":"Both papers read as abstracts only. The adhesion result in [PMID:11162558] is functional (antibody inhibition), not direct binding. One further paper was abstract_insufficient. Affinity not reported.","key_references":[{"PMID":"11162558","why":"alphaVbeta5 antibody blocks adhesion to ADAM9 disintegrin domain"},{"PMID":"15361064","why":"alphaV and beta1 chains captured by disintegrin domain"}],"covers":["LR000023","LR003573"]},"LR000032":{"pair":"ADM2 -> CALCRL","headline":"ADM2 (intermedin) activates CRLR/RAMP receptor complexes, with binding competition and in vivo effects; strong evidence, but CALCRL needs a RAMP.","interaction_type":"direct binding","direction_and_effect":"Intermedin raised cAMP and competed with labelled CGRP for binding in SK-N-MC and L6 cells with endogenous CGRP receptors; it is a nonselective agonist across RAMP1, 2 and 3 with CRLR in 293T cells. In vivo it lowered blood pressure in rats and suppressed gastric emptying in mice [PMID:14615490]. GtoPdb: full agonist [DB:GtoPdb].","molecular_requirements":"A CRLR/RAMP receptor complex is required; no RAMP preference [PMID:14615490]. Score as CALCRL plus a RAMP.","affinity_potency":[{"value":"pEC50 7.5-9.1","assay":"GtoPdb agonist record","system":"not given","cite":"DB:GtoPdb"},{"value":"pEC50 7.5-8.3","assay":"GtoPdb agonist record","system":"not given","cite":"DB:GtoPdb"}],"species_and_systems":"Recombinant 293T cells, endogenous-receptor cell lines, and rats and mice in vivo [PMID:14615490]; curators annotate human ligand and receptor. Mouse pair is projected from human.","localisation_and_range":"ADM2 is flagged secreted [flag]; acts as a circulating or paracrine peptide on a membrane receptor.","caveats":"Abstract-only. Binding was competition with labelled CGRP, not a direct ADM2 radioligand. Two further papers are review_only; the second confirmed paper is not shown.","key_references":[{"PMID":"14615490","why":"intermedin signals through CRLR/RAMP complexes; in vivo effects"}],"covers":["LR000032","LR003582"]},"LR000041":{"pair":"AGRP -> MC3R","headline":"AGRP is an antagonist of MC3R, supported by several abstract-read papers (functional, structural) and GtoPdb.","interaction_type":"direct binding","direction_and_effect":"Recombinant Agouti-related protein was a potent, selective antagonist of Mc3r and Mc4r [PMID:9311920]; it acts as a competitive antagonist of alpha-MSH at MC-3 and MC-4 receptors [PMID:9819197]. GtoPdb records the interaction as an antagonist with pIC50 units [DB:GtoPdb]. An NMR paper calls AGRP an endogenous antagonist of MC3R and MC4R [PMID:11747427].","molecular_requirements":"The AGRP C-terminal domain AGRP(87-132) has binding and antagonism equivalent to the full-length protein [PMID:11747427]. The RFF111-113 triplet is the most critical portion for MC3R and MC4R binding, and the Cys-110 to Cys-117 loop is critical for antagonist activity [PMID:9893984]. The synthetic octapeptides bound MC3R with lower affinity than MC4R [PMID:9893984].","affinity_potency":[{"value":"pIC50 7.7","assay":"competitive antagonism of alpha-MSH, bacterially expressed AGRP","system":"MC3R, human protein","cite":"PMID:9819197"}],"species_and_systems":"Recombinant or synthetic human AGRP on human receptors per curation tags; transgenic mice used for the obesity phenotype [PMID:9311920].","localisation_and_range":"AGRP is flagged secreted and non-transmembrane [flag]; AGRP is a hypothalamic neuropeptide in the abstract [PMID:9311920].","caveats":"All papers read as abstracts. The NMR structure is of the ligand alone, not a co-structure [PMID:11747427]. Human pair is not ortholog-inferred; mouse is.","key_references":[{"PMID":"9311920","why":"Recombinant AGRP is a potent, selective Mc3r/Mc4r antagonist; transgenic obesity"},{"PMID":"9819197","why":"Competitive antagonism of alpha-MSH at MC-3 and MC-4 receptors; pIC50 7.7"},{"PMID":"9893984","why":"Maps the RFF111-113 triplet and Cys110-Cys117 loop"}],"covers":["LR000041","LR003591"]},"LR000050":{"pair":"ALB -> LRP2","headline":"Megalin binds albumin in purified-receptor column binding and mediates its renal tubular uptake in rat; one paper, abstract only.","interaction_type":"direct binding","direction_and_effect":"Megalin acts as an uptake receptor: in rat proximal tubules in vivo, 125I-RSA uptake was inhibited by RAP (>50%) and by cold RSA; BSA-gold uptake was reduced by RAP to 17%, by EDTA to 19%, by BSA to 16% and by megalin to 35% [PMID:8898021].","molecular_requirements":"Megalin-Sepharose columns bound 125I-BSA and 125I-RSA, inhibited by RAP and EDTA [PMID:8898021].","affinity_potency":[],"species_and_systems":"Rat tubule microinfusion with rat and bovine albumin and purified megalin; the abstract does not give the megalin species. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"Endocytic receptor on proximal tubule; ligand flagged secreted [flag].","caveats":"Single paper, abstract only. No affinity. No database records.","key_references":[{"PMID":"8898021","why":"In vivo tubular uptake and megalin-column binding of albumin"}],"covers":["LR000050","LR003600"]},"LR006779":{"pair":"ALOX5AP -> ALOX5","headline":"Database-only support for an ALOX5AP-ALOX5 protein interaction; no curator-verified paper, and the pair is an enzyme-activating protein, not a classical ligand-receptor.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists ALOX5AP as an activator of ALOX5 (Action=Activation) [DB:GtoPdb]. UniProt notes ALOX5 interacts with ALOX5AP [DB:UniProt].","molecular_requirements":"BioGRID records a reconstituted complex of ALOX5 and ALOX5AP [DB:BioGRID]. Other requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species and system: not reported in our evidence; records are human-annotated.","localisation_and_range":"Not reported in our evidence beyond BioGRID co-localisation records [DB:BioGRID].","caveats":"No paper reached confirmed status: the two judged rows were abstract_insufficient and different_entity. Support is from databases alone.","key_references":[],"covers":["LR006779"]},"LR002102":{"pair":"ANGPT2 -> ITGAV","headline":"One abstract-only paper shows Ang2 interacting with alphaVbeta1 integrin and signalling in Tie2-deficient glioma cells.","interaction_type":"functional only","direction_and_effect":"Ang2 interacts with alpha(v)beta(1) integrin in Tie2-deficient human glioma cells, activating FAK, p130(Cas), ERK1/2 and JNK and enhancing MMP-2 expression and secretion; the curator labels it agonist and the pathway is Tie2-independent [PMID:16424009].","molecular_requirements":"Functional inhibition of both beta1 and alpha(v) integrins attenuated the pathway, so both chains are required; the measured receptor is alphaVbeta1, not alphaVbeta3 as the entity name suggests [PMID:16424009].","affinity_potency":[],"species_and_systems":"Human glioma cells and murine brain xenografts [PMID:16424009]; the mouse pair is ortholog-inferred.","localisation_and_range":"ANGPT2 is flagged as secreted [flag]; ITGAV is flagged as a receptor.","caveats":"Abstract only; the abstract reports 'interacts' and functional inhibition, not a direct binding measurement or affinity. The receptor entity name is alphaVbeta3 but the paper concerns alphaVbeta1. No database records for this pair.","key_references":[{"PMID":"16424009","why":"Ang2 signals via alphaVbeta1 integrin in Tie2-deficient glioma cells"}],"covers":["LR002102","LR005428"]},"LR002111":{"pair":"ANGPTL4 -> CDH5","headline":"cANGPTL4 is reported to bind VE-cadherin and decluster it, from a single abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"cANGPTL4 associates with VE-cadherin and declusters it after first activating integrin \u03b15\u03b21, disrupting endothelial continuity; curator labels it antagonist [PMID:21841165]. Knockout mice and tumour models show it induces vascular leakiness and lung metastasis [PMID:21841165].","molecular_requirements":"The acting ligand is the C-terminal fibrinogen-like domain (cANGPTL4), a proteolytic fragment, not full-length ANGPTL4 [PMID:21841165]. Binding to VE-cadherin follows a first step through integrin \u03b15\u03b21 and claudin-5 is a third partner; the sequence is temporal [PMID:21841165].","affinity_potency":[],"species_and_systems":"Human ligand and receptor per curator fields, with ANGPTL4-knockout versus wild-type mice in vivo [PMID:21841165]. The mouse pair is ortholog-inferred, not tested directly.","localisation_and_range":"ANGPTL4 is flagged secreted and CDH5 transmembrane [flag]; contact with endothelial junctions, acting from tumour-secreted ligand [PMID:21841165].","caveats":"Only one paper, read as abstract only; no affinity reported; binding method not stated in our evidence; fragment, not full-length, is the active form.","key_references":[{"PMID":"21841165","why":"cANGPTL4 binds VE-cadherin, integrin \u03b15\u03b21 and claudin-5 sequentially"}],"covers":["LR002111","LR005433"]},"LR002120":{"pair":"ANGPTL4 -> SDC3","headline":"Support is a computational ligand-receptor prediction from mouse heart scRNA-seq; no binding or functional test.","interaction_type":"database-asserted only","direction_and_effect":"A cell-communication analysis of mouse heart endothelial cells and cardiomyocytes in diabetes lists Angptl4-Sdc3 as one of four significant ligand-receptor pairs [PMID:40296165]. Effect direction is not reported in our evidence.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse heart single-cell RNA-seq (control and streptozotocin-induced diabetic mice) [PMID:40296165]. Human pair is ortholog-inferred.","localisation_and_range":"ANGPTL4 is flagged secreted [flag]; paracrine from endothelial cells to other cell types in the analysis [PMID:40296165].","caveats":"Inference from expression only; no experiment on this pair. Two further papers were judged abstract_insufficient.","key_references":[{"PMID":"40296165","why":"Predicts Angptl4-Sdc3 signalling in diabetic mouse heart"}],"covers":["LR002120","LR005442"]},"LR008678":{"pair":"APOC3 -> TLR2","headline":"One full-text co-immunoprecipitation in vascular smooth muscle cells supports APOC3 binding TLR2; single paper.","interaction_type":"direct binding","direction_and_effect":"Endogenous APOC3 co-immunoprecipitated with TLR2 in VSMCs, and the interaction was further enhanced under high-Pi stimulation [PMID:41734579]. The authors conclude ApoC3 inhibits AMPK/NRF2 signalling through TLR2, promoting ferroptosis and vascular calcification [PMID:41734579]. Agonist or antagonist role at TLR2 is not stated beyond this pathway.","molecular_requirements":"Not reported in our evidence (TLR2 co-receptors or subunits not addressed in the excerpts).","affinity_potency":[],"species_and_systems":"Pair is human; the experiments used primary rat VSMCs plus mouse (transgenic/knockout) and human arterial tissue [PMID:41734579].","localisation_and_range":"APOC3 is flagged secreted and TLR2 flagged receptor [flag].","caveats":"Co-IP shows association, not direct binding with purified proteins; no affinity. Only one confirmed paper; two further papers were judged abstract-insufficient and one review-only.","key_references":[{"PMID":"41734579","why":"Co-IP of endogenous APOC3 with TLR2 in VSMCs; full text"}],"covers":["LR008678"]},"LR012020":{"pair":"BAMBI -> ACVR1:ACVR2B","headline":"BAMBI to ACVR1:ACVR2B has no verified paper; support is limited to one BioGRID record that names a different receptor chain pair.","interaction_type":"database-asserted only","direction_and_effect":"The pair is annotated as Inhibitory [flag]; no paper in our evidence confirms this direction. BioGRID lists BMPR1B-BAMBI: Reconstituted Complex [DB:BioGRID 726964].","molecular_requirements":"Complex members are ACVR1 and ACVR2B; the BioGRID record concerns BMPR1B only, which is not a member of this complex [DB:BioGRID 726964]. Subunit requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the BioGRID experiment is not given; the pair is human.","localisation_and_range":"Receptor complex is flagged transmembrane [flag]; BAMBI has no annotation flags for secretion.","caveats":"Judged papers were abstract_insufficient or different_entity, so no paper confirms it; the evidence rests on a single database record.","key_references":[],"covers":["LR012020"]},"LR000104":{"pair":"BMP10 -> ACVR2A","headline":"BMP10 binds ACVR2A with Kd about 1 nM and signals through it; supported by SPR, shRNA and a database record.","interaction_type":"direct binding","direction_and_effect":"BMP10 bound ACVR2A-Fc in surface plasmon resonance, with ACVR2A GBD-Fc inhibiting BMP10 SMAD1/5/8 signalling in HEK293 reporter cells [PMID:35643319]. Knockdown of ActRIIA in MC3T3 cells suppressed BMP10 signalling [PMID:16049014]. BMP10 does not discriminate among ActRIIA, ActRIIB and BMPRII in binding to type II receptors [PMID:22718755]. GtoPdb: agonist [DB:GtoPdb]; BioGRID reconstituted complex [DB:BioGRID].","molecular_requirements":"Type I partners: ALK3 knockdown also suppressed BMP10 signalling [PMID:16049014]; ALK1 ternary complexes studied [PMID:22718755]. BMP10 also binds BMPR2 with high affinity [PMID:35643319].","affinity_potency":[{"value":"KD 1.0E-09 M","assay":"SPR (BMP10 over immobilised ACVR2A-Fc, single curve fit)","system":"recombinant proteins","cite":"PMID:35643319"}],"species_and_systems":"Recombinant human proteins (CHO-expressed receptors) and HEK293 cells [PMID:35643319]; MC3T3 cells [PMID:16049014]; kinetic analysis [PMID:22718755]. Human pair with mouse ortholog-inferred.","localisation_and_range":"BMP10 has a secreted flag and ACVR2A a transmembrane flag [flag].","caveats":"Two of three papers are abstract-only. Evidence for ACVR2A is part of multi-receptor studies; BMP10 binds several type II receptors.","key_references":[{"PMID":"35643319","why":"SPR binding and inhibition data for BMP10-ACVR2A"},{"PMID":"16049014","why":"ActRIIA knockdown suppresses BMP10 signalling"},{"PMID":"22718755","why":"BMP10 type II receptor binding without discrimination"}],"covers":["LR000104","LR003653"]},"LR000122":{"pair":"BMP2 -> ENG","headline":"Endoglin interacts with BMP-2 only through type I receptors ALK3/ALK6; indirect, one paper.","interaction_type":"functional only","direction_and_effect":"Endoglin interacts with BMP-2 but requires coexpression of the respective ligand-binding kinase receptor [PMID:9872992]. Its presence did not alter heteromeric signalling complex formation [PMID:9872992].","molecular_requirements":"Endoglin cannot bind BMP-2 on its own; binding requires the type I receptors ALK3 and ALK6 [PMID:9872992].","affinity_potency":[],"species_and_systems":"Affinity labelling in endothelial and leukemic cells; species not reported [PMID:9872992].","localisation_and_range":"Endoglin is a transmembrane glycoprotein [PMID:9872992]; BMP2 flagged secreted [flag].","caveats":"Only one paper, read as abstract. The interaction is accessory/co-receptor-like and not direct binding to endoglin. BioGRID lists affinity capture-western from the same paper [DB:BioGRID].","key_references":[{"PMID":"9872992","why":"endoglin binds BMP-2 via ALK3/ALK6"}],"covers":["LR000122","LR003671"]},"LR000131":{"pair":"BMP4 -> HJV","headline":"HJV (RGMC) binds BMP4 with Kd 4.5 nM by SPR and is a BMP4 co-receptor driving BMP signalling in hepatoma cells.","interaction_type":"direct binding","direction_and_effect":"SPR measured HJV binding to BMP4 with KD 4.5 nM, among the highest of the RGM-BMP pairs; RGMB bound BMP4 more tightly [PMID:23029472]. BMP-2, BMP-4 and BMP-6 are endogenous ligands for HJV in hepatoma-derived cell lines, with agonist effect on hepcidin regulation [PMID:18326817].","molecular_requirements":"HJV selectively used type II receptors ActRIIA and BMPRII, not ActRIIB, and enhanced ActRIIA use by BMP-2/BMP-4; HJV used ALK2/ALK3/ALK6 in vitro [PMID:18326817]. Action was independent of neogenin [PMID:18326817].","affinity_potency":[{"value":"KD 4.5 nM","assay":"surface plasmon resonance","system":"recombinant HJV and BMP4, human (curated)","cite":"PMID:23029472"}],"species_and_systems":"Recombinant SPR [PMID:23029472]; hepatoma-derived cell lines and human liver expression [PMID:18326817].","localisation_and_range":"HJV is flagged secreted and receptor [flag]; BMP4 secreted, so HJV may act as a co-receptor, membrane-bound or soluble.","caveats":"HJV acts as a co-receptor with BMP type I/II receptors, not alone. The functional paper was read as abstract only [PMID:18326817].","key_references":[{"PMID":"23029472","why":"SPR affinities of RGM proteins incl. HJV for BMP4"},{"PMID":"18326817","why":"HJV/BMP-4 signalling and receptor usage in hepatoma cells"}],"covers":["LR000131","LR003680"]},"LR000140":{"pair":"BMP7 -> ACVR2A","headline":"BMP7 binds the activin type II receptor ACVR2A directly; supported by a crystal structure, SPR and cell-binding data.","interaction_type":"direct binding","direction_and_effect":"BMP7 binds ACVR2A (ActR-II) as a type II receptor; a crystal structure of BMP7 with the ActRII extracellular domain was solved [PMID:12667445]. ActR-II acts as a functional type II receptor for BMP7 (OP-1): transcription was activated when OP-1 bound ActR-I plus ActR-II, or BMPR-IB plus ActR-II [PMID:7790373]. In P19 cells BMP7 and activin bind the same type II receptors, ActRII and IIB, but BMP7 recruits ALK2 as its main type I receptor [PMID:9748228]. GtoPdb lists an agonist action [DB:GtoPdb].","molecular_requirements":"ACVR2A is the type II chain; a type I receptor is also needed for signalling. The structure shows type I and type II ECDs make no direct contact, yet cooperative assembly occurs, and BMP7 affinity for its low-affinity type I receptor ECD rises 5-fold with the type II ECD present [PMID:12667445]. OP-1 binding to type I receptors was observed in the presence of ActR-II [PMID:7790373].","affinity_potency":[{"value":"KD(eq) 8.0 nM","assay":"SPR, immobilised ActR-II ECD, soluble BMP7","system":"recombinant human proteins","cite":"PMID:19735544"}],"species_and_systems":"Human recombinant proteins for the structure and SPR [PMID:12667445][PMID:19735544]; P19 embryonal carcinoma cells [PMID:9748228]; species of the OP-1 binding study not specified [PMID:7790373]. The dossier covers human and mouse pairs; the mouse pair is not ortholog-inferred, but no mouse-specific experiments are shown.","localisation_and_range":"BMP7 is flagged secreted and the receptor transmembrane [flag], suggesting paracrine signalling to a cell-surface receptor; the papers do not address range.","caveats":"Two papers (PMID 7790373, 9748228) were read as abstracts only. One further paper was judged abstract_insufficient. The OP-1 abstract reports ActR-II affinity as two- to threefold lower than that of activin A [PMID:7790373].","key_references":[{"PMID":"12667445","why":"Crystal structure of BMP7 with ActRII ECD and cooperative assembly"},{"PMID":"19735544","why":"SPR affinities of BMP7 for type I and II receptor ectodomains"},{"PMID":"7790373","why":"OP-1 binds ActR-II and signals with type I partners"}],"covers":["LR000140","LR003689"]},"LR011201":{"pair":"BMP8A -> ACVR1","headline":"BMP8A -> ACVR1 rests on a GtoPdb agonist record only; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP8A as an agonist at this receptor [DB:GtoPdb]; no paper was verified for this pair.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence.","localisation_and_range":"BMP8A is flagged secreted [flag]; range of action not otherwise reported.","caveats":"Support is a single database record with no affinity; one abstract was judged insufficient.","key_references":[],"covers":["LR011201"]},"LR006788":{"pair":"BMP8B -> ACVRL1","headline":"BMP8B -> ACVRL1 rests only on a GtoPdb agonist record; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP8B-ACVRL1 as Type=Agonist, Action=Agonist [DB:GtoPdb]; the interaction is annotated Stimulatory.","molecular_requirements":"Single receptor chain; co-receptors or partner chains are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence (human entities).","localisation_and_range":"Receptor flagged as a receptor [flag]; range not reported in our evidence.","caveats":"No curator-verified paper; several candidate papers were judged abstract-insufficient, review-only or about a different entity, so none supports the pair. The GtoPdb record is a database assertion, not an experiment.","key_references":[],"covers":["LR006788"]},"LR002210":{"pair":"C1QC -> CD44","headline":"CD44 mediates C1q signalling and chemotaxis in human neural stem cells; functional plus proximity-ligation support from one paper.","interaction_type":"functional only","direction_and_effect":"CRISPR-Cas9 CD44 knockout was used to test that CD44 mediates C1q-induced signalling (p-ERK) and chemotaxis in hNSC; the abstract reports CD44 mediates these effects in vitro and hNSC migration and repair in vivo after spinal cord injury [PMID:32894219]. Stimulatory.","molecular_requirements":"The ligand studied was assembled C1q (C1QA:C1QB:C1QC), not the single C1QC chain; chain-alone activity is not shown [PMID:32894219]. Co-receptor or subunit requirements on the CD44 side are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human neural stem cells in vitro (CD44 identified among five candidate C1q receptors by crosslinking and mass spectrometry, then proximity ligation assay indicating close contact <30 nm); in vivo spinal cord injury model, host species not stated in the excerpts [PMID:32894219].","localisation_and_range":"C1q is secreted (ligand flag); CD44 is flagged as transmembrane and also secreted [flag]. Acts on cell-surface CD44 of the responding cell [PMID:32894219].","caveats":"Curated from the abstract plus excerpts. Proximity ligation shows nearness, not a measured affinity; no Kd reported. Mouse interaction is ortholog-inferred only.","key_references":[{"PMID":"32894219","why":"CD44 identified as C1q receptor on hNSC; knockout abolishes C1q-induced signalling/chemotaxis"}],"covers":["LR002210","LR005523"]},"LR007949":{"pair":"CBLN1:NRXN1 -> GRID2","headline":"CBLN1:NRXN1 complex to GRID2 rests on a structure and UniProt text; no verified paper yet.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states CBLN1 induces presynaptic vesicle accumulation by binding NRXN1 and induces GRID2 clustering at the post-synaptic site [DB:UniProt]. GRID2 interacts with CBLN1 via its C1q domain [DB:UniProt].","molecular_requirements":"The PDB structure is of the Cbln1 C1q domain trimer with the amino-terminal domain of GluD2 and does not include NRXN1 [DB:PDB 5KCA]. So CBLN1 alone binds GRID2; whether NRXN1 is also required is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Crystal structure (X-ray diffraction) [DB:PDB 5KCA]; species not reported in our evidence.","localisation_and_range":"The complex is flagged transmembrane and not secreted, because of NRXN1 [flag]; CBLN1 alone is flagged secreted.","caveats":"Two papers are still pending. The complex ligand duplicates information in the CBLN1-GRID2 and CBLN1-NRXN1 pairs.","key_references":[{"PMID":"27418511","why":"Crystal structure of Cbln1 C1q with GluD2 ATD (PDB 5KCA)"}],"covers":["LR007949"]},"LR000212":{"pair":"CCL1 -> CCR8","headline":"Well supported cognate agonist pair: high-affinity binding and signalling in several human-receptor studies, plus GtoPdb and UniProt.","interaction_type":"direct binding","direction_and_effect":"CCL1 (I-309) is an agonist: it was the only one of 20 chemokines tested that induced Ca2+ mobilization and chemotaxis in CCR8-transfected cells [PMID:9211859], and signalling is pertussis-toxin-sensitive [PMID:9207005]. CCL1 activates MAPK in CCR8-transfected CHO cells and drives anti-apoptotic activity [PMID:12645948]. GtoPdb: full agonist [DB:GtoPdb].","molecular_requirements":"For mouse CCR8, mCCL1 depends on O-linked sulfation at tyrosines 14 and 15 [PMID:16221874].","affinity_potency":[{"value":"Kd 1.2 nM","assay":"125I-I-309 binding","system":"CCR8-transfected murine 300-19 cells","cite":"PMID:9211859"},{"value":"EC50 = 2 nM","assay":"calcium flux and chemotaxis","system":"CY6/CCR8-transfected mouse pre-B cells","cite":"PMID:9207005"},{"value":"Kd < 15 nM","assay":"binding fingerprint","system":"CCR8","cite":"PMID:10419462"}],"species_and_systems":"Human ligand and receptor in transfected cell lines; mouse BW5147 lymphoma cells and mCCR8 also used [PMID:12645948, PMID:16221874]. Only a human pair is listed.","localisation_and_range":"CCL1 flagged secreted, CCR8 transmembrane [flag].","caveats":"All papers read as abstracts. Viral chemokines vMIP-II and vMCC-I act as antagonists at CCR8 [PMID:10419462].","key_references":[{"PMID":"9211859","why":"Identification of CCR8 as I-309 receptor with Kd 1.2 nM"},{"PMID":"9207005","why":"CCR8 identified as the monogamous I-309 receptor"},{"PMID":"10419462","why":"CCR8 ligand binding fingerprint"}],"covers":["LR000212"]},"LR000203":{"pair":"CCL16 -> CCR8","headline":"CCL16 binds and activates human CCR8 in one transfected-cell study; other evidence is weak or discordant.","interaction_type":"direct binding","direction_and_effect":"CCL16 bound and activated CCR8-transfected HEK-293 cells, with maximal migration at 89.3 nmol/L and adhesion at 5.6 nmol/L [PMID:10910894]. UniProt lists CCL16 among CCR8 binders [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor in HEK-293 transfectants; abstract-only [PMID:10910894].","localisation_and_range":"Secreted ligand and transmembrane receptor according to entity annotation flags [flag]; paracrine/endocrine range implied by the secreted flag only.","caveats":"Migration needs 20- to 200-fold more CCL16 than RANTES or I309 [PMID:10910894]. Cross-paper concordance for CCR8 is not established in our evidence.","key_references":[{"PMID":"10910894","why":"CCL16 binding and activation of CCR8"}],"covers":["LR000203"]},"LR000221":{"pair":"CCL24 -> CCR3","headline":"CCL24 is an established CCR3 agonist, but our evidence for it is mostly indirect or background statements.","interaction_type":"functional only","direction_and_effect":"Agonist: CCR3 is described as a primary receptor for eotaxin-2 [PMID:15207250]. Eotaxin and eotaxin-2 chemotactic responses of dendritic cells were inhibited by CCR3-specific antibodies [PMID:12218106]. In CCR3-expressing L1.2 cells, calcium mobilisation potency ranked eotaxin, MCP-4 > eotaxin-3 > eotaxin-2, RANTES [PMID:10488147]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"CCR3 alone was used in these systems; no co-receptor requirement is reported in our evidence.","affinity_potency":[{"value":"pIC50 8.0-9.4","assay":"GtoPdb affinity range, unspecified assay","system":"database record","cite":"PMID:15207250"}],"species_and_systems":"Human ligand and receptor: engineered CHO cells [PMID:15207250], human dendritic cells [PMID:12218106], L1.2 transfectants [PMID:10488147]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag].","caveats":"PMID 16339911 names CCL24 only as background and gives no CCL24-specific data. PMID 15207250 and 12218106 treat the pairing as known, not newly shown. Abstracts only, except PMID 10488147 curated from browser reading, with spot-check pending.","key_references":[{"PMID":"12218106","why":"Antibody blockade of CCR3 inhibits dendritic-cell chemotaxis to eotaxin-2"},{"PMID":"10488147","why":"Relative CCR3 calcium potency of eotaxin-2"},{"PMID":"15207250","why":"High-expression CCR3 cell line used with eotaxins"}],"covers":["LR000221","LR003747"]},"LR000230":{"pair":"CCL28 -> CCR10","headline":"CCL28 is an agonist of CCR10, shown by calcium flux and chemotaxis in transfectants for human and mouse; supported by GtoPdb and Reactome.","interaction_type":"functional only","direction_and_effect":"CCL28 induces calcium mobilisation in CCR10-expressing transfectants and desensitises the CCL27 response, indicating a shared receptor [PMID:10781587]. Chemotaxis of CCR10-expressing lymphoid cells toward CCL28 is also reported [PMID:10975800]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain; no co-receptor or processed form reported in our evidence.","affinity_potency":[],"species_and_systems":"Both human and mouse CCL28 and CCR10 were tested in transfectants, so the mouse evidence is direct [PMID:10781587]; the second paper used human proteins [PMID:10975800].","localisation_and_range":"CCL28 is flagged as secreted and CCR10 as transmembrane [flag]; CCL28 is produced predominantly by epithelial cells and is expressed in mucosal tissues [PMID:10781587][PMID:10975800].","caveats":"Both papers were read as abstracts only and show function rather than binding; no affinity reported in our evidence. Reactome records the binding reaction 'CCR10 binds CCL27 and 28' [DB:Reactome].","key_references":[{"PMID":"10781587","why":"Identifies CCL28 as CCR10 ligand: calcium flux, human and mouse"},{"PMID":"10975800","why":"Independent chemotaxis of CCR10 transfectants to CCL28"}],"covers":["LR000230","LR003751"]},"LR006797":{"pair":"CCL7 -> CXCR3","headline":"Weak, single-source binding: MCP-3 competed for 125I-IP10 binding to human CXCR3 with Ki 250 nM; effect at the receptor is not shown.","interaction_type":"direct binding","direction_and_effect":"MCP-3 competed for 125I-IP10 binding to recombinant CXCR3 with Ki 250 nM [PMID:9660793]. GtoPdb lists it as an antagonist [DB:GtoPdb]; the paper's abstract shows antagonism only for eotaxin [PMID:9660793].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 250 nM","assay":"competition binding vs 125I-IP10 (table row)","system":"recombinant human CXCR3 in CHO cells","cite":"PMID:9660793"}],"species_and_systems":"Human ligand and receptor, CHO cells [PMID:9660793].","localisation_and_range":"CCL7 flagged secreted; CXCR3 flagged transmembrane receptor [flag].","caveats":"Moderate-to-weak affinity compared with IP10 (0.14 nM); the quote is a browser-read table row, unverified. No functional data for MCP-3.","key_references":[{"PMID":"9660793","why":"MCP-3 competes at CXCR3, Ki 250 nM"}],"covers":["LR006797"]},"LR001121":{"pair":"CCN3 -> NOTCH1","headline":"Non-canonical secreted CCN3 binds the NOTCH1 extracellular domain; effect on signalling is reported as both activating and inhibitory.","interaction_type":"conflicting","direction_and_effect":"CCN3 (NOV) associated with the NOTCH1 EGF-like repeats and activated the HES1 and HES5 promoters, a positive effect on Notch signalling [PMID:12050162]. In K562 leukaemia cells, overexpressed or recombinant CCN3 reduced NOTCH1 signalling (>50% reduction in NOTCH1-ICD), described as a non-canonical NOTCH1 ligand with inhibitory effect [PMID:24308033].","molecular_requirements":"The CCN3 C-terminal cysteine knot (CT) domain contacts the NOTCH1 EGF-like repeat region [PMID:12050162][DB:UniProt]. Other subunit or co-receptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Both papers used human proteins and cells (human CCN3 and NOTCH1, K562 cells for the second); the dossier lists both human and mouse pair records, with mouse experiments not described [PMID:12050162][PMID:24308033].","localisation_and_range":"CCN3 is flagged secreted and NOTCH1 transmembrane [flag], consistent with a paracrine ligand acting on a membrane receptor.","caveats":"The two papers disagree on the sign of the effect (activation of HES1/HES5 vs reduced NOTCH1-ICD). Both were read as abstracts only for binding; the binding evidence is domain-mapped association, with BioGRID affinity-capture and reconstituted-complex records from the same paper [DB:BioGRID]. No affinity reported.","key_references":[{"PMID":"12050162","why":"Domain-mapped CCN3 CT-NOTCH1 EGF-repeat association, HES1/HES5 activation"},{"PMID":"24308033","why":"CCN3 reduces NOTCH1-ICD in K562 CML cells"}],"covers":["LR001121","LR004532"]},"LR009569":{"pair":"CD55 -> ADGRE2","headline":"No papers support this pair; it rests on two database records.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human only; no experimental paper in the dossier.","localisation_and_range":"Annotation flags list the receptor as transmembrane and the ligand as secreted and transmembrane [flag].","caveats":"The only judged paper was classified as a different entity and not confirmed. IntAct lists a surface plasmon resonance record for the pair [DB:IntAct], and UniProt states ADGRE2 'Interacts with CD55' [DB:UniProt]. No paper-level validation, affinity or species detail.","key_references":[],"covers":["LR009569"]},"LR007958":{"pair":"CD93 -> IFNGR1","headline":"No paper support; one abstract judged insufficient; only IntAct binding assays from a single large study.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct lists a solid-phase assay and surface plasmon resonance for the UniProt pair [DB:IntAct]; species not stated in the dossier.","localisation_and_range":"Both partners are annotated as transmembrane [flag].","caveats":"No curated paper confirms this pair; support rests on database records only and may be a screen result.","key_references":[],"covers":["LR007958"]},"LR002300":{"pair":"CDH1 -> CDH1","headline":"E-cadherin homophilic binding is well established; ligation transduces growth-inhibitory signals.","interaction_type":"direct binding","direction_and_effect":"Recombinant E-cadherin on microspheres reduced S-phase entry and inhibited EGF-receptor-mediated growth signalling [PMID:17392517]. Database records include reconstituted complex, force spectroscopy and atomic force microscopy [DB:BioGRID] [DB:IntAct].","molecular_requirements":"Growth inhibition required E-cadherin binding to beta-catenin, not p120-catenin or alpha-catenin/actin coupling [PMID:17392517]. Reactome lists a calcium-bound dimer [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human epithelial cells with recombinant protein [PMID:17392517].","localisation_and_range":"Membrane-bound; juxtacrine homophilic adhesion [flag].","caveats":"Homotypic self-pair, so direction is not meaningful; one paper, abstract only.","key_references":[{"PMID":"17392517","why":"E-cadherin homophilic ligation inhibits growth"}],"covers":["LR002300","LR005598"]},"LR000302":{"pair":"CLCF1 -> CNTFR","headline":"The CLC/CLF composite cytokine binds membrane CNTFR; supported by binding, functional and structural records.","interaction_type":"direct binding","direction_and_effect":"The CLC/CLF composite cytokine preferentially interacted with the CNTFR subunit in membrane binding analysis [PMID:11294841]. It acts as an agonist, activating gp130, LIFR and STAT3 and enhancing motor neuron survival [PMID:10966616][PMID:11285233]. GtoPdb lists it as an agonist [DB:GtoPdb].","molecular_requirements":"The ligand is a CLC/CLF heterodimer; co-expression of CLC with CNTFR generated a secreted composite cytokine [PMID:11285233]. Membrane-bound CNTFR is required; soluble CNTFR did not substitute, unlike for CNTF [PMID:11294841]. Signalling needs gp130 and LIFR [PMID:10966616].","affinity_potency":[],"species_and_systems":"Human cells and proteins in all three papers (receptor reconstitution and mammalian cell co-expression); mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted, but the paper reports a membrane-bound CNTFR requirement [flag][PMID:11294841].","caveats":"All three papers were read as abstracts only. No affinity reported in our evidence. A cryo-EM structure of the CLCF1 signalling complex is listed [DB:PDB 8D7R].","key_references":[{"PMID":"11294841","why":"Membrane binding; membrane CNTFR required"},{"PMID":"10966616","why":"Identifies CLC/CLF heteromeric CNTFR ligand"},{"PMID":"11285233","why":"CLC-CNTFR composite cytokine activates gp130-LIFR"}],"covers":["LR000302","LR003808"]},"LR000311":{"pair":"CNTN2 -> NRCAM","headline":"Heterophilic TAG-1/NrCAM binding seen in a bead-aggregation assay in one paper.","interaction_type":"direct binding","direction_and_effect":"TAG-1-Fc beads formed mixed aggregates with NrCAM-Fc beads, and CHO cells with transmembrane NrCAM interacted with TAG-1 Fc chimeras [PMID:12139915]. Effect direction recorded as agonist.","molecular_requirements":"Total extracellular domain or Ig domains alone of TAG-1 sufficed for the cell interaction [PMID:12139915].","affinity_potency":[],"species_and_systems":"Human proteins as Fc chimeras and in CHO cells [PMID:12139915]. Both species ortholog-inferred. BioGRID lists reconstituted complex [DB:BioGRID].","localisation_and_range":"Cell adhesion, membrane contact based on the Fc-chimera and transfected-cell format [PMID:12139915].","caveats":"One paper confirms; four others abstract_insufficient. No affinity reported.","key_references":[{"PMID":"12139915","why":"Mixed aggregates of TAG-1 and NrCAM beads"}],"covers":["LR000311","LR003817"]},"LR000320":{"pair":"COL18A1 -> ITGB1","headline":"Endostatin binds alpha5beta1 by RGD-competable binding in one abstract-read paper; BioGRID and IntAct also list COL18A1-ITGB1.","interaction_type":"direct binding","direction_and_effect":"Human endostatin competes with fibronectin/RGD cyclic peptide to bind alpha5beta1 integrin; its antimigratory activity is mediated by that integrin [PMID:12682293].","molecular_requirements":"The partner is the alpha5beta1 heterodimer, so ITGB1 alone is not shown sufficient [PMID:12682293]. Ligand is endostatin, the NC1 fragment of collagen XVIII.","affinity_potency":[],"species_and_systems":"Human endostatin; abstract only [PMID:12682293]. BioGRID: reconstituted complex [DB:BioGRID, PMID:19542224]; IntAct: pull down [DB:IntAct, PMID:17615292].","localisation_and_range":"Ligand is a secreted fragment; receptor is membrane-bound.","caveats":"Abstract-only read; no affinity reported. Database records name ITGB1 without an alpha chain.","key_references":[{"PMID":"12682293","why":"Endostatin competes with RGD peptide to bind alpha5beta1"}],"covers":["LR000320","LR003826"]},"LR005699":{"pair":"COL5A1 -> ITGA2","headline":"Collagen V is linked to alpha2beta1 only through patient fibroblast genetics in an abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Fibroblasts from patients with COL5A1 mutations show reduced alpha2beta1, named as the functional receptor of collagens V and III; purified collagen V restored the control phenotype [PMID:14970208].","molecular_requirements":"Receptor is the alpha2beta1 heterodimer; blocking antibodies to alpha2beta1 induced an EDS-like phenotype in control cells [PMID:14970208].","affinity_potency":[],"species_and_systems":"Human dermal fibroblasts [PMID:14970208].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Disease genetics and antibodies, not a binding assay; abstract only.","key_references":[{"PMID":"14970208","why":"Fibroblasts with COL5A1 mutations lose alpha2beta1"}],"covers":["LR002420","LR005699"]},"LR006995":{"pair":"COL8A1 -> ITGA11:ITGB1","headline":"COL8A1-ITGB1 interaction reported in colorectal and pancreatic cancer abstracts; the ITGA11 chain itself is not tested.","interaction_type":"functional only","direction_and_effect":"In colorectal cancer, COL8A1 secreted from THBS2+ CAFs is reported to directly interact with ITGB1 on resistant malignant cells, activating PI3K-AKT signaling and promoting EMT and oxaliplatin resistance [PMID:39732719]. In PDAC cells, ITGB1 and DDR1 activation, PI3K/AKT and NF-\u03baB signaling occurred downstream of COL8A1 [PMID:36375776].","molecular_requirements":"Evidence names ITGB1 only; the ITGA11 subunit is not mentioned in our evidence, so the alpha-chain requirement is not reported. Full-text excerpts of PMID:39732719 describe CellChat COL8A1-ITGB1 inference, spatial colocalisation and molecular docking, not subunit requirements [PMID:39732719].","affinity_potency":[],"species_and_systems":"Human colorectal cancer and PDAC cells; both papers read as abstract, with excerpts for PMID:39732719.","localisation_and_range":"Ligand flagged secreted [flag]; CAF-to-tumor-cell paracrine/matrix signaling in the CRC study [PMID:39732719].","caveats":"Complex-level support rests on ITGB1 alone; part of the support is computational (CellChat, spatial colocalisation, docking). Four further rows are review-only.","key_references":[{"PMID":"39732719","why":"COL8A1 from CAFs interacts with ITGB1 in CRC"},{"PMID":"36375776","why":"COL8A1 activates ITGB1/DDR1 signaling in PDAC"}],"covers":["LR006995"]},"LR003899":{"pair":"CXCL10 -> CXCR3","headline":"CXCL10 is a well-established agonist of CXCR3, with binding, potency and in vivo support in human and mouse.","interaction_type":"direct binding","direction_and_effect":"CXCL10 binds CXCR3 and acts as an agonist [PMID:9064356][PMID:9660793]; potency order was CXCL11 >> CXCL10 > CXCL9 [PMID:15761110]. In mouse cells, CXCL10-induced migration depended on CXCR3 through ERK activation [PMID:28724396]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"CXCR3 alone mediated migration; for osteoclastogenic cytokines CXCR3 and TLR4 were both needed [PMID:28724396]. CXCL10 heparin/GAG binding was separable from CXCR3 binding [PMID:12571234].","affinity_potency":[{"value":"Ki 0.14 nM","assay":"binding of IP10 to heterologously expressed CXCR3","system":"human CXCR3","cite":"PMID:9660793"},{"value":"KD 1.35 nM","assay":"ligand binding to murine CXCR3","system":"murine CXCR3 in L1.2 pre-B cells","cite":"PMID:10556837"}],"species_and_systems":"Human receptor and ligand in transfected cells [PMID:9660793]; murine CXCR3 transfectants [PMID:10556837]; mouse murine IP-10 on CHO-expressed CXCR3 [PMID:12571234]; primary mouse cells and arthritis model [PMID:28724396].","localisation_and_range":"CXCL10 is flagged secreted and CXCR3 transmembrane [flag].","caveats":"Mostly abstract-level reads. CXCL10 also antagonises CCR3 [PMID:12884299].","key_references":[{"PMID":"9660793","why":"Pharmacology of CXCR3 with IP10 and MIG"},{"PMID":"9064356","why":"Cloning of the IP10/Mig receptor"},{"PMID":"28724396","why":"CXCR3-dependent CXCL10 signalling in mouse arthritis"}],"covers":["LR000393","LR003899"]},"LR000401":{"pair":"CXCL12 -> CXCR4","headline":"Canonical, extensively supported agonist interaction with direct binding, signalling and structures; nanomolar affinities reported in several human systems.","interaction_type":"direct binding","direction_and_effect":"SDF-1 was identified as the natural ligand of LESTR/fusin, renamed CXCR4, inducing Ca2+ and chemotaxis in transfected cells [PMID:8752280, PMID:8752281]. Binding and signalling were confirmed in T cell lines (chemotaxis, Ca2+ rise, internalisation) [PMID:9551924], and chemotaxis in HUVEC was blocked by anti-CXCR4 [PMID:10233851]. GtoPdb lists it as agonist [DB:GtoPdb]. HMGB1 forms a heterocomplex with CXCL12 that signals only via CXCR4 [PMID:22370717].","molecular_requirements":"The CXCL12 N-terminal 9 residues are sufficient for activation; the dimer of 1-9 was active and a 1-9[P2G] dimer was an antagonist [PMID:9712844]. CXCR4 can heteromerise with ChemR23, with negative binding cooperativity [PMID:23469143]. A single chain is enough; no co-receptor is required in the evidence.","affinity_potency":[{"value":"Kd 1.23 nM","assay":"125I-SDF-1alpha competitive binding, Scatchard","system":"HUVEC","cite":"PMID:10233851"},{"value":"Kd between 5 and 10 nM","assay":"Scatchard of SDF-1alpha binding","system":"human T cell lines","cite":"PMID:9551924"},{"value":"pIC50 9.3","assay":"125I-CXCL12 competition binding","system":"hCXCR4 in HEK293T membranes","cite":"PMID:30476826"},{"value":"half-maximal chemoattractant activity 5 nM","assay":"chemotaxis of native SDF-1","system":"T lymphocytes/CEM cells","cite":"PMID:9712844"},{"value":"pKd 7.7-8.2","assay":"GtoPdb affinity range","system":"curated database","cite":"PMID:9551924"}],"species_and_systems":"Mostly human ligand and receptor in primary cells and cell lines; some experiments used mouse cells (3T3, bone marrow) [PMID:22370717]. Human and mouse pairs are listed.","localisation_and_range":"CXCL12 is flagged secreted and CXCR4 transmembrane [flag]; acts on cells as a soluble chemokine.","caveats":"Several papers are abstract-only. Four rows are functional (survival, migration, heteromer) rather than binding. PDB structures exist (e.g. 2K03, 8K3Z) [DB:PDB 2K03]. CXCR4 and ACKR3 are both receptors for CXCL12 per UniProt [DB:UniProt].","key_references":[{"PMID":"8752281","why":"De-orphanisation of CXCR4 by SDF-1"},{"PMID":"9551924","why":"Kd, signalling, internalisation in T cells"},{"PMID":"30476826","why":"Radioligand competition on hCXCR4 (pIC50 9.3)"}],"covers":["LR000401","LR003906"]},"LR000410":{"pair":"CXCL2 -> CXCR2","headline":"Well supported agonist interaction: high-affinity binding and potent signalling in human receptor transfectants, plus a GtoPdb record and structures.","interaction_type":"direct binding","direction_and_effect":"Agonist: GRObeta/CXCL2-class ELR+ chemokines are potent agonists at IL8RB (CXCR2) by calcium flux, competing for high-affinity binding [PMID:8702798]. CXCL2-induced ASMC migration depended on p38 MAPK and CXCR2 [PMID:23904157]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"No co-receptor requirement reported in our evidence. PDB entries 8XVU and 8XXH contain a CXCL2 chain and a CXCR2 chain [DB:PDB 8XVU].","affinity_potency":[{"value":"Kd 5.7 nM","assay":"binding of recombinant murine MIP-2 to human type B IL-8 receptor","system":"recombinant","cite":"PMID:9260277"},{"value":"EC50 4 nM","assay":"calcium flux, GRObeta at IL8RB","system":"HEK293 transfectants","cite":"PMID:8702798"},{"value":"pIC50 7.0 to 9.1","assay":"GtoPdb affinity range","system":"database record","cite":"DB:GtoPdb"}],"species_and_systems":"Human receptor in HEK293 cells and human primary ASMCs [PMID:8702798][PMID:23904157]; murine MIP-2 on human receptor and on murine receptor (Kd 6.8 nM) [PMID:9260277].","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag], so paracrine signalling to a cell-surface receptor is implied; paper text does not address range.","caveats":"Mostly abstract-only reads. PMID:8550564 names GROalpha, not CXCL2, so it supports CXCL2 only by analogy within the selectivity group. Ligand identity in the EC50 listing (GRObeta) is an alias-based assignment.","key_references":[{"PMID":"8702798","why":"Potency and competition binding at IL8RB"},{"PMID":"9260277","why":"Kd for MIP-2 at human and murine receptors"},{"PMID":"23904157","why":"CXCL2 migration via CXCR2 in ASMCs"}],"covers":["LR000410","LR003912"]},"LR003989":{"pair":"EFNA4 -> EPHA8","headline":"Ephrin-A4 Fc binds EphA8 in cells and by ELISA; direct binding evidence.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A1 and ephrin-A4 chimeric ligands efficiently bound EphA8 in NIH3T3 fibroblasts, with EphA8 tyrosine phosphorylation on stimulation [PMID:10515610]. Ephrin-A4 Fc binds most EphA receptors with high apparent affinity [PMID:22568954].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Fc-fusion ligands on EphA8-expressing NIH3T3 cells (human recorded for both partners) [PMID:10515610]; ELISA, species unspecified [PMID:22568954]. The human pair is ortholog-inferred.","localisation_and_range":"EFNA4 flagged secreted and transmembrane; EPHA8 flagged membrane-bound [flag].","caveats":"10515610 was an abstract-only read; 22568954 a browser read with an unverifiable quote.","key_references":[{"PMID":"10515610","why":"Ephrin-A4-Fc binds and activates EphA8"},{"PMID":"22568954","why":"ELISA of ephrin-A4 Fc across EphA receptors"}],"covers":["LR000498","LR003989"]},"LR005789":{"pair":"EFNA5 -> ADAM10","headline":"ADAM10 cleaves ephrin-A5 within an ephrin-A5/EphA3 complex; a protease-substrate relation, not a classic ligand-receptor pair.","interaction_type":"functional only","direction_and_effect":"ADAM10 constitutively associates with EphA3; the functional EphA3/ephrin-A5 complex creates a new recognition motif for the ADAM10 cysteine-rich domain, enabling ephrin-A5 cleavage in trans [PMID:16239146]. UniProt describes a ternary EFNA5-EPHA3-ADAM10 complex mediating shedding [DB:UniProt].","molecular_requirements":"Needs EphA3 bound to ephrin-A5; ADAM10 disintegrin and cysteine-rich domains are the recognition module [PMID:16239146].","affinity_potency":[],"species_and_systems":"Mouse system per the curator record [PMID:16239146]; human pair listed, mouse is ortholog-inferred.","localisation_and_range":"EFNA5 flagged membrane-bound; ADAM10 flagged receptor but not secreted [flag]. Cleavage occurs in trans across opposing cells [PMID:16239146].","caveats":"Interaction is mediated through EphA3, not a direct EFNA5-ADAM10 binding result in our evidence. Three other judged rows were a different entity. Read as an abstract only.","key_references":[{"PMID":"16239146","why":"ADAM10 recognises the ephrin-A5/EphA3 complex and cleaves ephrin-A5"}],"covers":["LR002521","LR005789"]},"LR000500":{"pair":"EFNA5 -> EPHA2","headline":"Soluble ephrin-A5 (LERK-7) induces EphA2 (eck) phosphorylation; crystal structures of the complex exist in PDB.","interaction_type":"direct binding","direction_and_effect":"A soluble form of LERK-7 (EFNA5) induced phosphorylation of eck in a human duodenum adenocarcinoma cell line [PMID:9245480]. PDB holds structures of EphA2 ectodomain with ephrin-A5 [DB:PDB 2X11] [DB:PDB 3MX0]; IntAct lists light scattering and pull-down records [DB:IntAct].","molecular_requirements":"The PDB 2X11 entry covers the complete EphA2 ectodomain with the ephrin-A5 receptor-binding domain [DB:PDB 2X11].","affinity_potency":[],"species_and_systems":"Human cancer cell line [PMID:9245480]; the species of the structural work is not reported in our evidence. Mouse pair is ortholog-inferred.","localisation_and_range":"Both flagged membrane-bound [flag]; the paper reports GPI-anchored LERK-7 with a soluble form active [PMID:9245480].","caveats":"The only confirmed paper is a functional abstract-only read; the identity of eck as EPHA2 comes from a curator note, and binding rests on database structural records.","key_references":[{"PMID":"9245480","why":"Soluble LERK-7 induces eck phosphorylation"}],"covers":["LR000500","LR003991"]},"LR003998":{"pair":"EFNA5 -> EPHB2","headline":"Well supported direct binding, including a crystal structure; a cross-class (A-ephrin to B-receptor) pair.","interaction_type":"direct binding","direction_and_effect":"Ephrin-A5 binds EphB2 with high affinity; exposing EphB2 cells to it caused receptor clustering, autophosphorylation, downstream signalling, growth cone collapse and neurite retraction [PMID:15107857]. Annotated stimulatory.","molecular_requirements":"The complex is a heterodimer by X-ray crystallography, distinct from the tetrameric EphB2-ephrin-B2 structure [PMID:15107857].","affinity_potency":[],"species_and_systems":"Cell-based and structural work annotated human [PMID:15107857]; an ELISA with Fc fusion proteins also showed ephrin-A5 binding EphB2, with species unspecified [PMID:22568954]. Pair listed for human and mouse, both ortholog-inferred.","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"No numeric affinity in our evidence; the abstract only says 'high affinity'. The ELISA paper was read through a browser and its quote is marked unverified [PMID:22568954].","key_references":[{"PMID":"15107857","why":"Binding, signalling and heterodimer structure of ephrin-A5/EphB2"},{"PMID":"22568954","why":"ELISA confirms ephrin-A5 binding to EphB2"}],"covers":["LR000507","LR003998"]},"LR004001":{"pair":"EFNB1 -> EPHB2","headline":"Functional reverse-signalling evidence into ephrin-B1 cells on EphB2-Fc exposure; direct binding data absent from our evidence.","interaction_type":"functional only","direction_and_effect":"EphB2-Fc stimulation induced RhoA activation and enhanced motility and invasiveness of ephrinB1-expressing cells [PMID:29059157]. Clustered Nuk ectodomain induced tyrosine phosphorylation of the transmembrane ligands Elk-L or Htk-L [PMID:8878483]. So signalling runs into the ephrin-B1 cell (reverse).","molecular_requirements":"RhoGDI1 binds ephrinB1 (amino acids 327-334), and binding is enhanced by EphB2 extracellular domain [PMID:29059157].","affinity_potency":[],"species_and_systems":"Human cancer lines (SW480, Hs578T) were used for knockdown [PMID:29059157]; the other study used cells expressing the ligands and Nuk, species not specified [PMID:8878483]. UniProt says ephrin-B1 can also bind EPHB2 [DB:UniProt].","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"Both papers abstract-level; neither measures affinity. Elk-L/Htk-L naming and Nuk=EphB2 are curator mappings. IntAct solid phase record [DB:IntAct].","key_references":[{"PMID":"29059157","why":"EphB2-Fc drives ephrinB1/RhoGDI1/RhoA signalling"},{"PMID":"8878483","why":"Nuk ectodomain induces ligand tyrosine phosphorylation"}],"covers":["LR000510","LR004001"]},"LR004010":{"pair":"EFNB2 -> EPHB2","headline":"Strongly supported direct binding with a 2.7 A co-crystal structure and functional repulsion data.","interaction_type":"direct binding","direction_and_effect":"Crystal structure of the EphB2-ephrin-B2 complex at 2.7 A resolution [PMID:11780069]. EphB2 is cleaved by MMPs on ephrin-B2 interaction, which enables repulsive signalling [PMID:18713744]. Annotated stimulatory.","molecular_requirements":"Each Eph binds one ephrin through a dimer interface; two dimers form a tetramer promoting higher-order clustering [PMID:11780069]. MMP-2/MMP-9 cleavage of the EphB2 ectodomain is needed for repulsion in HEK293 cells [PMID:18713744].","affinity_potency":[],"species_and_systems":"Species curator-annotated human [PMID:11780069]; HEK293 cells and hippocampal neurons for cleavage [PMID:18713744]. ELISA also supports binding [PMID:22568954]. BioGRID: reconstituted complex [DB:BioGRID].","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"No numeric affinity in our evidence. Abstract-level reading. Growth-cone data in the cleavage paper used ephrin-B1.","key_references":[{"PMID":"11780069","why":"Crystal structure of EphB2/ephrin-B2 complex"},{"PMID":"18713744","why":"Ephrin-B2-induced MMP cleavage of EphB2 for repulsion"}],"covers":["LR000519","LR004010"]},"LR005798":{"pair":"EPHA1 -> EFNA1","headline":"EPHA1-EFNA1 rests on UniProt statements only; no curator-verified papers.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states EFNA1 binds EPHA1 with high affinity and calls it the probable cognate ligand, while EFNA1 'also binds with low affinity to EPHA1' in another entry [DB:UniProt]. These two UniProt statements disagree on affinity.","molecular_requirements":"Subunits or co-receptors: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence; both human and mouse pairs are ortholog-inferred.","localisation_and_range":"EPHA1 is flagged non-secreted transmembrane; EFNA1 is flagged both secreted and transmembrane [flag], which is inconsistent. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Two review-only rows, no verified primary paper. Affinity claims conflict within UniProt.","key_references":[],"covers":["LR002530","LR005798"]},"LR005879":{"pair":"FAM3B -> FGFR4","headline":"FAM3B is reported as an FGFR ligand in one Xenopus paper; FGFR4-specific evidence is thin.","interaction_type":"functional only","direction_and_effect":"The paper shows FAM3B as an FGFR ligand in Xenopus, with ERK activation via FGFR1 [PMID:33975953]. Purified human FAM3B was incubated with Fc-tagged human FGFR1-4 ectodomains, with FGFR4-Ecto-Fc one of the panels; the excerpts do not show the FGFR4 result itself [PMID:33975953].","molecular_requirements":"FGFR1 kinase-inactive mutant with intact ectodomain still bound FAM3B; no co-receptor requirement reported [PMID:33975953]. Whether FGFR4 acts alone: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Xenopus embryos, HEK293T cells and recombinant human FAM3B; curation row labels species human [PMID:33975953].","localisation_and_range":"FAM3B is secreted [flag] and detected in HEK293T medium [PMID:33975953].","caveats":"Single paper. The abstract does not say which of FGFR1-4 binds; all four rows rest on a family-level claim, and the main system is Xenopus [PMID:33975953]. No affinity reported. FGF family paralog overlap is possible.","key_references":[{"PMID":"33975953","why":"FAM3B binds FGFR ectodomain and activates ERK in Xenopus/HEK293T"}],"covers":["LR002612","LR005879"]},"LR008975":{"pair":"FGB -> ITGAM","headline":"Functional-only support: one abstract-read paper shows fibrinogen adhesion of eosinophils blocked by anti-alphaMbeta2.","interaction_type":"functional only","direction_and_effect":"Airway eosinophils adhered to fibrinogen among other ligands, and the enhanced adhesion was blocked by anti-alphaMbeta2; IL-5 reproduced the effect in blood eosinophils [PMID:16601240]. Effect direction is not reported in our evidence.","molecular_requirements":"The receptor assayed is the alphaMbeta2 (ITGAM:ITGB2) heterodimer and the ligand the fibrinogen heterohexamer (FGA/FGB/FGG); this resource encodes both by their chains, so the evidence is not specific to FGB or ITGAM alone [PMID:16601240].","affinity_potency":[],"species_and_systems":"Eosinophils purified from airway and blood; species not stated in the abstract [PMID:16601240].","localisation_and_range":"FGB is flagged secreted [flag]; ITGAM is flagged as a non-secreted receptor [flag]. Cell-adhesion context suggests contact with matrix-bound or soluble fibrinogen, but the paper text does not say so.","caveats":"Adhesion readout with antibody blockade, not a binding measurement. Abstract only. No database record supports this pair. Chain-level encoding of complexes.","key_references":[{"PMID":"16601240","why":"Only paper: fibrinogen adhesion of eosinophils blocked by anti-alphaMbeta2"}],"covers":["LR008975"]},"LR005897":{"pair":"FGF2 -> ITGB3","headline":"FGF2 binds integrin alphavbeta3 and its integrin-binding mutants antagonise FGF2 signalling; evidence concerns the heterodimer.","interaction_type":"direct binding","direction_and_effect":"WT FGF2 bound immobilised soluble \u03b1v\u03b23 on SPR, and integrin-binding-defective FGF2 mutants were inactive and suppressed WT FGF2 signalling in NIH3T3 cells and endothelial cells [PMID:28302677]. UniProt notes ITGAV:ITGB3 binds FGF2 and is essential for FGF2 signalling [DB:UniProt].","molecular_requirements":"Evidence is for \u03b1v\u03b23, so \u03b23 needs its \u03b1v partner; \u03b15\u03b21 binding was also suggested [PMID:28302677].","affinity_potency":[{"value":"Kd 7.75 \u00d7 10\u22128 M","assay":"SPR, WT FGF2 on immobilised soluble \u03b1v\u03b23","system":"recombinant, in vitro","cite":"PMID:28302677"}],"species_and_systems":"Human recombinant proteins; NIH3T3 (mouse) and HUVEC cell assays [PMID:28302677]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted, receptor non-secreted [flag].","caveats":"The curated evidence sentence is background from earlier work. Docking and interface mapping are predicted. Single paper.","key_references":[{"PMID":"28302677","why":"FGF2-\u03b1v\u03b23 SPR binding and antagonist mutants"}],"covers":["LR002631","LR005897"]},"LR004100":{"pair":"FGF2 -> SDC2","headline":"FGF2 binds syndecan-2 via heparan sulfate in a pull-down, and syndecan-2 raises FGF2 binding to FGFR1 in cells.","interaction_type":"direct binding","direction_and_effect":"FGF2-GST bound human SDC2 via heparitinase-cleavable HS in HEK293T cells [PMID:16982797]. Cotransfected syndecan-2 with FGFR1 raised specific 125I-bFGF binding two- to three-fold in K562 cells [PMID:8609172]. BioGRID and IntAct list co-purification, affinity-capture and co-IP records [DB:BioGRID; DB:IntAct].","molecular_requirements":"Binding is via HS chains [PMID:16982797]; syndecans contribute to FGF2-FGFR1 complex formation [PMID:8609172].","affinity_potency":[],"species_and_systems":"Human cells (HEK293T, K562) [PMID:16982797; PMID:8609172]. Mouse pair is ortholog-inferred.","localisation_and_range":"SDC2 is flagged transmembrane, FGF2 secreted [flag].","caveats":"FGF2 was a positive-control ligand in one paper; binding is to HS chains, which is not specific to SDC2. Several other papers were abstract_insufficient or review_only, and one is pending.","key_references":[{"PMID":"16982797","why":"FGF2-GST pull-down of SDC2 via HS"},{"PMID":"8609172","why":"Syndecan-2 cotransfection increases FGF2 binding"}],"covers":["LR000616","LR004100"]},"LR005969":{"pair":"GPNMB -> EGFR","headline":"GPNMB binds the EGFR C-terminus and activates mutated EGFR without EGF in NSCLC cells; one paper plus database records.","interaction_type":"direct binding","direction_and_effect":"GPNMB activated mutated EGFR without ligand stimulation, bound the EGFR C-terminus, assisted Y845 phosphorylation, turned on STAT3 signalling and promoted metastasis [PMID:33706413]. Agonist-like, ligand-independent. A different model has GPNMB in a complex with EGFR under HB-EGF stimulation [DB:Reactome].","molecular_requirements":"N134 glycosylation of GPNMB is crucial: depleting it greatly reduced binding to mutated EGFR [PMID:33706413]. Binding to mutated EGFR (especially L858R) was stronger than to wild-type EGFR [PMID:33706413].","affinity_potency":[],"species_and_systems":"Human NSCLC cells with EGFR mutations, plus in vivo metastasis experiments [PMID:33706413]. Wild-type EGFR binding was weaker.","localisation_and_range":"GPNMB is flagged as secreted [flag]; the paper treats it as a transmembrane glycoprotein [PMID:33706413], so contact-dependent action is plausible but not tested here.","caveats":"Effect is largely specific to mutated EGFR. The paper itself contrasts its model with a reported HB-EGF-dependent complex in breast cancer [PMID:33706413]. BioGRID, IntAct and Reactome records rest on PMID 26751287 [DB:BioGRID] [DB:IntAct] [DB:Reactome].","key_references":[{"PMID":"33706413","why":"N-glycosylated GPNMB binds and activates mutated EGFR"}],"covers":["LR002704","LR005969"]},"LR011999":{"pair":"GREM2 -> BMP7","headline":"Recombinant PRDC (curated as GREM2) bound BMP7 directly; one abstract-only paper, with a mouse protein.","interaction_type":"direct binding","direction_and_effect":"Recombinant mouse PRDC bound directly to BMP2, BMP4 and BMP7, but not activin A, and inhibited BMP2 and BMP4 in a luciferase reporter assay [PMID:22381466]. The interaction is annotated as inhibitory [flag]. BMP7 inhibition itself was not tested in the abstract.","molecular_requirements":"Functional protein required oxidative refolding and separation from a nonfunctional component [PMID:22381466].","affinity_potency":[],"species_and_systems":"Recombinant mouse PRDC expressed in E. coli, tested by binding assay in vitro; the pair listed is human [PMID:22381466].","localisation_and_range":"BMP7 is flagged as secreted and non-transmembrane [flag]; this is a secreted ligand-ligand (antagonist) pair.","caveats":"Abstract only; no affinity value reported in our evidence. The dossier equates PRDC with GREM2 via curation, not stated in the abstract. Two other papers were abstract_insufficient.","key_references":[{"PMID":"22381466","why":"Direct binding of recombinant mouse PRDC to BMP2, BMP4 and BMP7"}],"covers":["LR011999"]},"LR005978":{"pair":"HGFAC -> LRP1","headline":"Direct LRP1 binding of HGFAC shown in a chondrocyte ligandome study (abstract only); a scavenger-type endocytic receptor interaction.","interaction_type":"direct binding","direction_and_effect":"Purified LRP1 binds HGFAC directly, one of ten ligands confirmed in this way; LRP1 affinity correlated with endocytosis rate across these ligands [PMID:36028175]. This indicates LRP1 acts as an endocytic receptor, not a signalling agonist target; the paper's effect label was agonist, which is not clearly supported [PMID:36028175].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human chondrocytes and purified proteins, with a conditional Lrp1-knockout mouse model used for the wider ligandome; the dossier does not say that HGFAC itself was tested in mice [PMID:36028175].","localisation_and_range":"HGFAC and LRP1 are annotated as secreted and as a receptor respectively [flag].","caveats":"One paper read as an abstract; HGFAC is one of ten ligands covered in a single sentence and no HGFAC-specific affinity is reported. No database records.","key_references":[{"PMID":"36028175","why":"Direct LRP1 binding of HGFAC among ten chondrocyte ligands"}],"covers":["LR002713","LR005978"]},"LR011012":{"pair":"HLA-DQA2 -> CD4","headline":"Class II MHC binding to CD4 is structurally shown, but with human CD4 and murine I-A(k), not HLA-DQA2.","interaction_type":"direct binding","direction_and_effect":"The crystal structure shows the CD4 N-terminal two-domain fragment contacting a class II MHC; this is a co-receptor interaction [PMID:11535811].","molecular_requirements":"Only the top corner of CD4 contacts peptide-MHC II, with Phe-43 inserting into a hydrophobic pocket [PMID:11535811]. Which MHC II chain is contacted: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human CD4 fragment with murine I-A(k) class II MHC plus peptide, purified proteins, X-ray crystallography [PMID:11535811].","localisation_and_range":"Not reported in our evidence.","caveats":"Cross-species complex; HLA-DQA2 itself was not tested. Abstract only. The DQA2 chain is a class II alpha chain, and specificity for it is unknown.","key_references":[{"PMID":"11535811","why":"Crystal structure of human CD4 with murine I-A(k)"}],"covers":["LR011012"]},"LR005987":{"pair":"HMGB1 -> TLR2","headline":"HMGB1 acts as an agonist of TLR2 in a glioma model; functional evidence only, from one abstract-level paper plus database notes.","interaction_type":"functional only","direction_and_effect":"HMGB1 released from dying tumour cells acts as an endogenous TLR2 ligand on GBM-infiltrating dendritic cells; the anti-tumour response is TLR2-dependent, and glycyrrhizin or anti-HMGB1 blocks TLR2 activation by tumour supernatants and abolishes efficacy in vivo [PMID:19143470]. UniProt notes apoptotic HMGB1:nucleosome complexes can signal through TLR2 [DB:UniProt].","molecular_requirements":"Not reported in our evidence; UniProt describes TLR2 signalling via CD14 and TLR4:LY96/TLR2 complexes for endotoxin transfer [DB:UniProt]. IntAct lists a co-immunoprecipitation [DB:IntAct].","affinity_potency":[],"species_and_systems":"Mouse glioma models and bone-marrow-derived dendritic cells; the curator lists HMGB1 as human and TLR2 as mouse [PMID:19143470]. The mouse pair is listed without ortholog inference; the human pair is ortholog-inferred.","localisation_and_range":"HMGB1 is flagged as secreted [flag]; the paper shows release from dying tumour cells acting on nearby dendritic cells [PMID:19143470].","caveats":"Paper read as abstract and excerpts only. No direct binding measurement is reported; the evidence is inhibition and TLR2-dependence. The paper's text notes HMGB1 can also activate TLR4 [PMID:19143470].","key_references":[{"PMID":"19143470","why":"Mouse glioma model: HMGB1 as TLR2 ligand, blocked by glycyrrhizin and antibody"}],"covers":["LR002739","LR005987"]},"LR005996":{"pair":"HSP90AA1 -> LRP1","headline":"Extracellular HSP90alpha is reported to engage LRP1/CD91; direct binding and functional evidence from two papers.","interaction_type":"direct binding","direction_and_effect":"Fluorescent hsp90 binds RAW264.7 and related cells via CD91, shown by alpha2-macroglobulin competition and anti-CD91 blockade [PMID:11290339]. Extracellular Hsp90alpha with clusterin promotes EMT, AKT/ERK/NFkB activation and migration in breast cancer cells, mediated by LRP1 [PMID:31273033].","molecular_requirements":"Clusterin joins the eHsp90alpha-LRP1 complex and enhances Hsp90alpha binding affinity to LRP1 [PMID:31273033].","affinity_potency":[],"species_and_systems":"Mouse macrophage-type cell lines [PMID:11290339]; human breast cancer cells [PMID:31273033]. BioGRID lists co-localisation and reconstituted-complex records [DB:BioGRID].","localisation_and_range":"HSP90AA1 carries no secreted flag [flag], but the paper studies extracellular Hsp90alpha [PMID:31273033].","caveats":"The 2001 paper shows direct CD91 binding only for gp96 (earlier work); hsp90 binding there is on cells. The 2019 paper was read as abstract only; no Kd reported. One further row was abstract_insufficient.","key_references":[{"PMID":"11290339","why":"hsp90 binds cells via CD91, competed by alpha2-macroglobulin and anti-CD91"},{"PMID":"31273033","why":"Extracellular Hsp90alpha acts through LRP1; clusterin enhances binding"}],"covers":["LR002748","LR005996"]},"LR008948":{"pair":"HSP90B1 -> TLR9","headline":"Database records only; no curator-verified paper supports this pair as a ligand-receptor interaction.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"UniProt states HSP90B1 interacts with TLR4 and TLR9, but not with TLR3 [DB:UniProt]. Species of the experiments is not reported in our evidence beyond the human entities.","localisation_and_range":"The ligand carries no secreted flag [flag]; localisation of the interaction is not reported in our evidence.","caveats":"No verified paper; the judged row was different_entity.","key_references":[],"covers":["LR008948"]},"LR008579":{"pair":"ITGA9:ITGB1 -> VCAM1","headline":"Integrin alpha9beta1 with VCAM1 is asserted by UniProt and Reactome; no paper judged.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states integrin alpha-9/beta-1 is a receptor for VCAM1, cytotactin and osteopontin [DB:UniProt]. Reactome lists an alpha9beta1:VCAM-1 complex [DB:Reactome].","molecular_requirements":"Both ITGA9 and ITGB1 are in the complex [DB:UniProt]. IntAct has cross-linking associations [DB:IntAct].","affinity_potency":[],"species_and_systems":"No experimental paper judged for this pair; species is human per the record.","localisation_and_range":"Both partners carry receptor flags and VCAM1 is flagged transmembrane [flag]; contact-mediated adhesion is implied by the plasma membrane complexes listed [DB:Reactome].","caveats":"Database support only; two pending papers not judged.","key_references":[],"covers":["LR008579"]},"LR011003":{"pair":"LAMA4 -> ITGA2:ITGB1","headline":"Evidence concerns LAMA4 with ITGB1 only; nothing in our evidence tests the alpha2 chain.","interaction_type":"functional only","direction_and_effect":"In E14.5 mouse brain, LAMA4 and ITGB1 proteins overlapped by immunofluorescence, and the authors state they experimentally confirmed the LAMA4-ITGB1 interaction [PMID:31677479].","molecular_requirements":"Only ITGB1 was examined; ITGA2 is not mentioned in the evidence [PMID:31677479].","affinity_potency":[],"species_and_systems":"Mouse E14.5 brain sections, with predicted interactions based on mouse gene expression [PMID:31677479].","localisation_and_range":"LAMA4 is flagged secreted [flag]; the paper says LAMA4 lies in the extracellular matrix around endothelial cells [PMID:31677479].","caveats":"Co-localisation is not binding, and the abstract-based confirmation does not address the alpha2 subunit.","key_references":[{"PMID":"31677479","why":"LAMA4-ITGB1 overlap in developing brain"}],"covers":["LR011003"]},"LR011030":{"pair":"LAMA5 -> SV2A","headline":"Alpha5-containing 900-kDa laminin is complexed with SV2 on nerve-terminal synaptosomes; a single abstract-only paper.","interaction_type":"functional only","direction_and_effect":"SV2 is complexed with an alpha5-containing 900-kDa laminin on synaptosomes, and the authors suggest it may act as a laminin receptor on the presynaptic membrane [PMID:10617638]. Annotated stimulatory.","molecular_requirements":"The laminin is a 900-kDa alpha5/beta1/novel-gamma isoform; direct binding of SV2 was tested only with purified laminin-1, which has no alpha5 chain [PMID:10617638].","affinity_potency":[],"species_and_systems":"Curator fields record rat; the abstract describes electric-organ synaptosomes [PMID:10617638]. Human relevance not reported in our evidence.","localisation_and_range":"LAMA5 is flagged secreted [flag]. SV2A is a synaptic vesicle protein, so receptor use needs surface exposure at the terminal [PMID:10617638]. No receptor flag is recorded for SV2A.","caveats":"Co-complex evidence, not direct binding of the alpha5 laminin. The high-affinity binding was to laminin-1 (no affinity value given in our evidence). Abstract-only read.","key_references":[{"PMID":"10617638","why":"SV2 co-complexed with alpha5-containing laminin on synaptosomes"}],"covers":["LR011030"]},"LR001013":{"pair":"LAMC1 -> ITGB4","headline":"Laminin (via LAMC1) engages integrin alpha6beta4 in a cell-adhesion assay; functional evidence from one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Laminin supported attachment of alpha6beta4-positive cells under fluid shear stress, and an anti-alpha6 antibody inhibited attachment and detached adherent cells [PMID:7699012]. Recorded effect: stimulatory [flag].","molecular_requirements":"The assayed ligand is the laminin heterotrimer (LAMA1/LAMB1/LAMC1) and the binder is the alpha6beta4 heterodimer, so LAMC1 and ITGB4 are chain-level proxies [PMID:7699012]. Laminin fragment E8 also supported attachment [PMID:7699012].","affinity_potency":[],"species_and_systems":"Human and other epithelial/carcinoma cell lines in laminar-flow adhesion assays; species of cell lines not stated in our evidence. Mouse pair is ortholog-projected.","localisation_and_range":"LAMC1 is flagged secreted [flag]; the assay used laminin as a substrate.","caveats":"Abstract only; no binding constants; no direct binding of LAMC1 to ITGB4 shown; one paper; antibody against alpha6, not beta4. A beta1 antibody did not inhibit rapid attachment [PMID:7699012].","key_references":[{"PMID":"7699012","why":"Laminin adhesion under flow mediated by alpha6beta4"}],"covers":["LR001013","LR004431"]},"LR007976":{"pair":"LCK -> CD8A:CD8B","headline":"Intracellular LCK-CD8 alpha binding, supported by a PDB NMR structure and UniProt; not a secreted ligand-receptor pair.","interaction_type":"direct binding","direction_and_effect":"UniProt states CD8 alpha (P01732) interacts with LCK in a zinc-dependent manner [DB:UniProt], and LCK interacts with the CD8 entry P10966 [DB:UniProt]. A solution NMR structure of CD8 alpha and LCK fragments exists [DB:PDB 1Q69].","molecular_requirements":"Structure covers the CD8 alpha chain and an LCK fragment; the role of CD8 beta is not reported in our evidence [DB:PDB 1Q69].","affinity_potency":[],"species_and_systems":"Species not reported in our evidence.","localisation_and_range":"LCK is not flagged secreted [flag]; CD8A:CD8B is flagged transmembrane [flag].","caveats":"Interaction class is Receptor-Receptor, so this is a signalling-partner association rather than a ligand-receptor pair. No curated papers: two were abstract-insufficient, one different-entity.","key_references":[],"covers":["LR007976"]},"LR001022":{"pair":"LEP -> LRP2","headline":"Megalin (LRP2) binds and internalises leptin in rat cells, a clearance rather than signalling interaction.","interaction_type":"direct binding","direction_and_effect":"Megalin bound leptin in the presence of Ca(2+) and mediated its internalisation and degradation, indicating a clearance receptor role [PMID:15131016]. No signalling effect reported in our evidence.","molecular_requirements":"Binding was calcium dependent [PMID:15131016]. Co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Ligand blotting, quartz-crystal microbalance and degradation assays in megalin-expressing rat yolk sac L2 cells; histoautoradiography in rats with 125I-leptin. Curators list human leptin with rat receptor. Human and mouse pairs are ortholog-inferred [PMID:15131016].","localisation_and_range":"Circulating leptin is filtered by glomeruli and internalised by proximal convoluted tubules, where megalin is expressed; LEP-R localised to other nephron segments [PMID:15131016].","caveats":"Abstract-only read. This is scavenger/clearance biology, so a CCC tool may mislead if read as signalling; no database records.","key_references":[{"PMID":"15131016","why":"Megalin binds and degrades leptin in renal proximal tubules"}],"covers":["LR001022","LR004440"]},"LR001031":{"pair":"LPL -> GPIHBP1","headline":"GPIHBP1 binds LPL and chylomicrons on capillary endothelium; supported by one abstract-only paper plus structural and interaction databases.","interaction_type":"direct binding","direction_and_effect":"Expression of GPIHBP1 in cultured cells conferred binding of both LpL and chylomicrons; Gpihbp1-deficient mice accumulated chylomicrons, with plasma triglycerides as high as 5000 mg/dl [PMID:17403372]. GPIHBP1 acts as a platform for LpL-mediated chylomicron processing [PMID:17403372]. UniProt states that interaction with GPIHBP1 protects LPL against inactivation by ANGPTL4 [DB:UniProt].","molecular_requirements":"UniProt reports a 1:1 stoichiometry between LPL and GPIHBP1 [DB:UniProt]. Reactome describes GPIHBP1 binding an HSPG:LPL dimer [DB:Reactome]. Crystal structures of the two proteins are listed [DB:PDB 6E7K].","affinity_potency":[],"species_and_systems":"Paper labels experiments human; the abstract itself mentions mouse knockouts and cultured cells [PMID:17403372]. The mouse pair is ortholog-inferred.","localisation_and_range":"GPIHBP1 is on the luminal face of capillary endothelium in heart and adipose tissue [PMID:17403372]. LPL is annotated secreted [flag].","caveats":"Paper read as abstract only. Affinity not reported in our evidence. IntAct lists ELISA and affinity-technology records [DB:IntAct].","key_references":[{"PMID":"17403372","why":"GPIHBP1 binds LpL and chylomicrons; knockout mice show chylomicronemia"}],"covers":["LR001031","LR004445"]},"LR001040":{"pair":"LTA -> TNFRSF1A","headline":"Well supported direct binding: crystal structure of the TNFR1:LT-beta (LTA) complex plus binding evidence and several databases.","interaction_type":"direct binding","direction_and_effect":"Curator labels agonist. The crystal structure shows three receptor molecules bound symmetrically to one TNF beta trimer, with the receptor in the groove between adjacent subunits, giving a model for receptor activation [PMID:8387891]. LT alpha2/beta1 surface complex is recognised by the p55-TNF receptor [PMID:7995952].","molecular_requirements":"The LT alpha trimer binds three TNFR1 molecules [PMID:8387891]. UniProt says LTA in its homotrimeric form binds TNFR1 [DB:UniProt]. Reactome lists LTA trimer binding TNFRSF1A,1B,14 [DB:Reactome]; structure [DB:PDB 1TNR].","affinity_potency":[],"species_and_systems":"Human proteins; structure used the extracellular domain of human 55 kd TNF receptor and human TNF beta at 2.85 A resolution [PMID:8387891]. Surface-complex work used PMA-activated II-23 human T cell hybridoma [PMID:7995952].","localisation_and_range":"LT alpha is flagged secreted and the receptor transmembrane [flag]. Surface LT alpha2/beta1 is a minor membrane form that p55 recognises [PMID:7995952].","caveats":"Both papers read as abstracts only. The surface-form paper concerns a heteromer and does not isolate LT alpha. No affinity in our evidence. BioGRID lists co-crystal and reconstituted complexes [DB:BioGRID].","key_references":[{"PMID":"8387891","why":"Crystal structure of TNFR1 with LT alpha (TNF beta)"},{"PMID":"7995952","why":"Minor LT-alpha2/beta1 surface form recognised by p55 receptor"}],"covers":["LR001040","LR004453"]},"LR001103":{"pair":"NLGN1 -> NRXN2","headline":"Neuroligin-neurexin binding is reported for beta-neurexins as a class; NRXN2 is not individually resolved. Abstract-level.","interaction_type":"direct binding","direction_and_effect":"Binding studies show all three neuroligins bind beta-neurexins, as native brain and recombinant proteins [PMID:8576240]. Direction/effect on NRXN2 specifically is not reported in our evidence.","molecular_requirements":"Tight binding was seen only for beta-neurexins lacking an insert in splice site 4 [PMID:8576240].","affinity_potency":[],"species_and_systems":"Species unspecified in the dossier for this row [PMID:8576240]; mouse and human pairs are ortholog-projected.","localisation_and_range":"Neither partner is secreted; both carry transmembrane flags [flag], so this is a membrane-bound, contact-dependent (trans-synaptic) pair. BioGRID lists NRXN2-NLGN1 as a reconstituted complex [DB:BioGRID].","caveats":"The paper reports 'beta-neurexins' as a class, so NRXN2 is not individually shown. Abstract only; two further papers were abstract-insufficient. No affinity.","key_references":[{"PMID":"8576240","why":"Neuroligin binding to beta-neurexins"}],"covers":["LR001103","LR004514"]},"LR001112":{"pair":"NMB -> NMBR","headline":"Well-supported direct agonist-receptor pair: radioligand binding and signalling in human cells, plus mutagenesis and antisense work.","interaction_type":"direct binding","direction_and_effect":"NMB acts as an agonist: it stimulates inositol phosphate formation in cells expressing human NMBR [PMID:7838118], and NMBR antisense blocks NMB-induced colonic smooth muscle contraction [PMID:8253343].","molecular_requirements":"Single receptor chain; no co-receptor reported in our evidence. Ile216 in transmembrane domain V is critical for high-affinity NMB binding [PMID:8392057].","affinity_potency":[{"value":"Ki = 8.1 +/- 5.2 nM","assay":"agonist competition binding","system":"human NMBR in BALB/3T3 fibroblasts","cite":"PMID:7838118"},{"value":"EC50 = 9.3 +/- 1.4 nM","assay":"[3H]inositol phosphate generation","system":"human NMBR in BALB/3T3 fibroblasts","cite":"PMID:7838118"},{"value":"IC50 0.052-0.054 nM","assay":"radioligand competition binding (as stated in full-text excerpt: 'high affinity (i.e. 0.052-0.054 nM)')","system":"hNMBR-containing human cell lines","cite":"PMID:21729729"}],"species_and_systems":"Experiments are mainly human receptors in transfected or cancer cell lines [PMID:7838118][PMID:21729729]; human and rabbit colon smooth muscle for antisense [PMID:8253343]; Xenopus oocytes for cloned receptor [PMID:1655761]. The mouse pair is inferred from human by orthology.","localisation_and_range":"NMB is flagged secreted and NMBR transmembrane [flag], so paracrine signalling is likely; the papers do not address range.","caveats":"Most papers were read as abstracts only; only PMID:21729729 was read in full. PMID:10454496 supports competitive binding of an antagonist with NMB, not NMB affinity itself. The mouse entry has no experiments of its own in our evidence.","key_references":[{"PMID":"7838118","why":"Human NMBR affinity and EC50 for NMB, with ~600-fold selectivity over GRP"},{"PMID":"21729729","why":"Full-text human binding data for NMB at hNMBR cell lines"},{"PMID":"8392057","why":"Mutagenesis: Ile216 in TM-V needed for high-affinity binding"}],"covers":["LR001112","LR004523"]},"LR001130":{"pair":"NPPB -> NPR1","headline":"BNP activates NPR1 (GC-A) nearly as potently as ANP; abstract-level and mouse in vivo support.","interaction_type":"functional only","direction_and_effect":"Via GC-A, BNP is nearly as potent as ANP and much more potent than CNP in cGMP production [PMID:1309330]. Supraphysiological ANP and BNP lowered systolic blood pressure by about 30 mm Hg in normotensive mice [PMID:39261724].","molecular_requirements":"NPR1 is a membrane-bound guanylate cyclase producing cGMP on agonism [PMID:39261724]; no subunit requirement reported.","affinity_potency":[],"species_and_systems":"Human/bovine/rat preparations [PMID:1309330]; BNP tested in mice (ortholog) [PMID:39261724]. UniProt notes BNP binding NPR1 [DB:UniProt].","localisation_and_range":"BNP is annotated secreted [flag].","caveats":"PMID:1309330 was read as abstract only and notes marked species differences, especially for BNP. PMID:39261724 is mainly about an agonist antibody; BNP is a comparator.","key_references":[{"PMID":"1309330","why":"Relative potency of ANP, BNP, CNP at GC-A"},{"PMID":"39261724","why":"In vivo BP effects of ANP/BNP via NPR1 in mice"}],"covers":["LR001130","LR004540"]},"LR002999":{"pair":"NPTX1 -> NPTXR","headline":"NPTXR is enriched on NP1 affinity columns; one abstract-level paper, no databases.","interaction_type":"direct binding","direction_and_effect":"NPR (NPTXR) was enriched by affinity chromatography on columns of NP1, NP2 and a toxin [PMID:9261167]. Direction or effect not reported in our evidence.","molecular_requirements":"NPTXR has a putative N-terminal transmembrane domain and is glycosylated; NPR shares 49% identity with NP1 [PMID:9261167].","affinity_potency":[],"species_and_systems":"Affinity chromatography; species not stated in dossier [PMID:9261167]. Both pairs ortholog-inferred.","localisation_and_range":"NPTXR is a putative integral membrane pentraxin [PMID:9261167]; NPTX1 annotated secreted [flag].","caveats":"Single abstract-only paper; pulldown shows association, not affinity. Pentraxin family paralogs complicate interpretation.","key_references":[{"PMID":"9261167","why":"Identification of NPR as NP1-binding protein"}],"covers":["LR002999","LR006223"]},"LR003002":{"pair":"NRCAM -> CNTN2","headline":"NRCAM-CNTN2 is supported by two database records only; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"No paper confirms this pair. BioGRID lists a reconstituted complex [PMID:12139915][DB:BioGRID] and Reactome lists an NrCAM:Axonin-1 complex [DB:Reactome R-HSA-445006].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the database experiments not reported in our evidence; human and mouse pairs are ortholog-inferred.","localisation_and_range":"Both entities carry secreted, receptor and transmembrane-type annotation flags [flag]; these look conflicting for a cell adhesion pair and do not define range. Contact-mediated binding is not shown here.","caveats":"No verified paper: outcomes are two different_entity and six abstract_insufficient. Support is database-only and the direction (ligand versus receptor) is not established.","key_references":[],"covers":["LR003002","LR006226"]},"LR008597":{"pair":"NRG2 -> ERBB2:ERBB4","headline":"NRG2 binds ErbB4 directly and a soluble ErbB2/4 heterodimer binds it; ERBB2 role is not isolated.","interaction_type":"direct binding","direction_and_effect":"The NRG-2 EGF-like domain binds ErbB3 and ErbB4, yet drives a different ErbB phosphorylation profile from NRG-1 [PMID:9168115]. Neuregulin-2beta only activated cell lines with ErbB3 and/or ErbB4 [PMID:9168114].","molecular_requirements":"The ErbB2/4 heterodimer bound all ligands tested, NRG2beta among the eleven, with moderate to very high affinity [PMID:10214951]. Binding of NRG2 to ErbB4 itself is direct [PMID:9168115]; ERBB2 contribution is not separated.","affinity_potency":[],"species_and_systems":"Human ligand and receptor; receptor binding assays and soluble receptors [PMID:10214951]; adult rat tissue was used for expression [PMID:9168114].","localisation_and_range":"NRG2 is flagged secreted and transmembrane [flag].","caveats":"All three papers are abstract only; no affinity values for NRG2 are quoted in our evidence. Recombinant NRG2beta induced ErbB2 phosphorylation only in cells with ErbB3/ErbB4 [PMID:9168114], so ERBB2 is not a direct target.","key_references":[{"PMID":"9168115","why":"NRG-2 EGF domain binds ErbB4 and ErbB3"},{"PMID":"10214951","why":"ErbB2/4 heterodimer binds NRG2beta"},{"PMID":"9168114","why":"NRG2 cloning and ErbB3/4-restricted activation"}],"covers":["LR008597"]},"LR003011":{"pair":"NRN1 -> CD36","headline":"NRN1 binds CD36 in a CRISPRa screen follow-up by cell staining; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Fluorescent tetramers of NRN1 bound 293F cells expressing full-length CD36 by flow cytometry, and CD36 was a top hit in the NRN1 screen [PMID:36178190]. Effect on CD36 is not reported.","molecular_requirements":"Full-length CD36 on the cell surface; NRN1 was used as a tetramer, which can favour low-affinity interactions [PMID:36178190]. Other subunits not reported.","affinity_potency":[],"species_and_systems":"Human NRN1 and CD36; CRISPR activation screen and 293F cells, recombinant [PMID:36178190].","localisation_and_range":"NRN1 annotated as secreted [flag]; CD36 is a multi-pass transmembrane scavenger receptor [PMID:36178190].","caveats":"Tested by cell surface staining only (no SPR for this pair in the paper table) [PMID:36178190]. No affinity. CD36 also bound other secreted ligands (LY6H, VWC2L, SCRG1), so it may be promiscuous. In vivo relevance not reported.","key_references":[{"PMID":"36178190","why":"CRISPRa screen identifies CD36 as NRN1 receptor, confirmed by staining"}],"covers":["LR003011","LR006235"]},"LR003020":{"pair":"NRXN1 -> LRRTM3","headline":"In vitro pull-down shows LRRTM3 interacts with neurexin-1beta lacking SS4; one confirmed paper, mouse.","interaction_type":"direct binding","direction_and_effect":"Ig-neurexin-1b lacking an insert at SS4 pulled down LRRTM3 in vitro; LRRTM3 required only specific neurexin splice variants for synaptogenic activity [PMID:26776509].","molecular_requirements":"Pull-down used SS4-lacking neurexin-1beta; the abstract states LRRTM3 needs specific splice variants of presynaptic neurexins [PMID:26776509].","affinity_potency":[],"species_and_systems":"Mouse study (Lrrtm3 knockout and knockdown in dentate gyrus neurons) [PMID:26776509]. Human pair is ortholog-inferred. UniProt notes NRXN1 interacts with LRRTM1-4 by similarity [DB:UniProt].","localisation_and_range":"Both transmembrane [flag]; trans-synaptic.","caveats":"The paper itself says the interaction was shown at least in vitro; the binding is a supplementary figure result, not the main finding. One further paper was abstract_insufficient.","key_references":[{"PMID":"26776509","why":"Ig-neurexin-1b pull-down of LRRTM3; splice-variant-dependent synaptogenesis"}],"covers":["LR003020","LR006244"]},"LR001202":{"pair":"PDYN -> OPRK1","headline":"Dynorphin A is a high-affinity agonist at the kappa opioid receptor, with binding in human and guinea pig and database records.","interaction_type":"direct binding","direction_and_effect":"Dynorphin A (1-17) bound human kappa receptor with high affinity [PMID:7869844]; the guinea pig receptor showed high affinity and stereospecificity toward dynorphin peptides and coupled to inhibit adenylyl cyclase and Ca2+ channels [PMID:8170987]. GtoPdb lists Agonist, Full agonist [DB:GtoPdb]. A biosensor paper used kappa receptor activation to report dynorphin release in mouse [PMID:39009835].","molecular_requirements":"Single receptor chain is sufficient in the cloned expression systems [PMID:7869844][PMID:8170987].","affinity_potency":[{"value":"pKi 8.0 to 9.9","assay":"GtoPdb affinity range, agonist","system":"not reported in our evidence","cite":"PMID:1967312"},{"value":"pKi 8.3 to 10.2","assay":"GtoPdb affinity range, agonist","system":"not reported in our evidence","cite":"PMID:7869844"}],"species_and_systems":"Human receptor in COS-1 cells [PMID:7869844]; guinea pig receptor in COS-7 cells [PMID:8170987]; mouse brain slices and in vivo with a kappa-receptor sensor [PMID:39009835]. All read as abstracts (the last with some full text).","localisation_and_range":"PDYN flagged secreted; the biosensor paper reports dynorphin volume transmission in brain slices [PMID:39009835].","caveats":"Binding papers are abstract-only; the guinea pig paper does not name PDYN-derived peptides by symbol. The 2024 biosensor paper is a tool paper, not a binding test. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"7869844","why":"Human kappa receptor binds dynorphin A (1-17) with high affinity"},{"PMID":"8170987","why":"Guinea pig kappa receptor: dynorphin affinity and signalling"},{"PMID":"39009835","why":"Mouse biosensor detecting dynorphin release via kappa receptor"}],"covers":["LR001202","LR004611"]},"LR001211":{"pair":"PF4 -> LDLR","headline":"PF4 binds the ligand-binding domain of soluble LDL-R and partly blocks LDL binding; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"PF4 partially (about 50%) inhibited LDL binding and reduced LDL-R-dependent LDL binding, internalization and degradation by 50%, 80% and 80% [PMID:11986215]. It acts as a competitive inhibitor, not an agonist.","molecular_requirements":"Cell-associated chondroitin sulfate proteoglycans were required for inhibition of internalization and degradation; heparin-binding-impaired PF4 variants were inactive [PMID:11986215].","affinity_potency":[{"value":"half-maximal binding 0.5 microg/mL PF4","assay":"binding to recombinant soluble LDL-R","system":"in vitro","cite":"PMID:11986215"}],"species_and_systems":"Cultured human cells and recombinant soluble LDL-R; ligand and receptor recorded as human [PMID:11986215].","localisation_and_range":"PF4 is flagged secreted [flag].","caveats":"Abstract only. Effect is inhibitory despite database modulatory label Stimulatory. BioGRID lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"11986215","why":"PF4 binds LDL-R and inhibits LDL catabolism"}],"covers":["LR001211"]},"LR008894":{"pair":"PIGF -> FLT1","headline":"PIGF binds soluble Flt-1 with high affinity but not Flk-1/KDR; supported by one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"PIGF proteins bound with high affinity to Flt-1 and failed to bind Flk-1/KDR [PMID:7929268]. 125I-PIGF binding to human endothelial cells showed two site classes; the high-affinity site is consistent with Flt-1 [PMID:7929268]. Agonist or antagonist effect on FLT1: not reported in our evidence.","molecular_requirements":"Both isoforms, PIGF131 and PIGF152, were made as recombinant homodimers; the abstract states both bound Flt-1 [PMID:7929268].","affinity_potency":[],"species_and_systems":"Recombinant PIGF isoforms expressed in mammalian cells; soluble VEGF receptors and human endothelial cells [PMID:7929268]. Ligand/receptor species of the soluble receptors: not reported in our evidence.","localisation_and_range":"No localisation flags given beyond the pair being a growth factor binding a transmembrane receptor [flag].","caveats":"Abstract only; no numeric affinity in our evidence. Purified PIGF had little or no direct mitogenic or permeability-enhancing activity, but potentiated low-concentration VEGF [PMID:7929268].","key_references":[{"PMID":"7929268","why":"PIGF binds Flt-1 but not Flk-1/KDR; isoforms characterised"}],"covers":["LR008894"]},"LR003101":{"pair":"PILRA -> CD8A","headline":"PILRA is reported as a ligand for CD8A in mouse and human; one abstract-only paper, no binding data in our evidence.","interaction_type":"direct binding","direction_and_effect":"PILR-alpha was identified as a ligand for CD8-alpha in both mice and humans, and disrupting the interaction broke CD8+ T cell quiescence [PMID:35617401]. Which partner signals to which in practice: PILRA is the ligand and CD8A the receptor as curated; effect on CD8+ T cells is maintenance of quiescence [PMID:35617401].","molecular_requirements":"Chain or co-receptor requirements (for example CD8B): not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse and human; inducible CD8-alpha deletion in CD8+ T cells in peripheral lymphoid organs [PMID:35617401]. Binding method: not reported in our evidence.","localisation_and_range":"Both entities carry secreted, receptor and transmembrane flags [flag], so form (soluble versus membrane) is unclear.","caveats":"Abstract only; the binding assay is not described in our evidence, so physical binding rests on the curator's reading of 'identified as a ligand'. Evidence class is direct_binding but detail is a functional quiescence assay [PMID:35617401].","key_references":[{"PMID":"35617401","why":"CD8-alpha-PILR-alpha interaction maintains CD8+ T cell quiescence"}],"covers":["LR003101"]},"LR003110":{"pair":"PLAUR -> ITGA4","headline":"Direct cell-based binding of soluble uPAR to alpha4 (ITGA4) integrin chain in one paper; no affinity.","interaction_type":"direct binding","direction_and_effect":"Soluble uPAR (suPAR D2D3) bound integrin-transfected CHO cells in a cation-dependent manner, blocked by anti-integrin and anti-uPAR antibodies [PMID:11053440]. It acts as a ligand, signalling consequence not reported in our evidence.","molecular_requirements":"Evidence is for the heterodimer; the integrin chain alone was not tested separately [PMID:11053440]. Partner chain beta1 is the paired subunit reported [PMID:11053440].","affinity_potency":[],"species_and_systems":"Human uPAR on hamster (CHO) cells [PMID:11053440].","localisation_and_range":"uPAR is described as a GPI-anchored protein lacking a transmembrane structure that acts as an integrin ligand, in trans between apposed cells, as well as an associated protein in cis [PMID:11053440]. Cell-cell contact range.","caveats":"Single paper (full text); no affinity.","key_references":[{"PMID":"11053440","why":"uPAR binds integrins alpha4beta1, alpha6beta1, alpha9beta1, alphavbeta3 on CHO cells"}],"covers":["LR003110","LR006331"]},"LR001301":{"pair":"RLN3 -> RXFP2","headline":"Relaxin-3 shows only variable activity at RXFP2 in one abstract-read paper; weak support.","interaction_type":"functional only","direction_and_effect":"Synthetic human relaxin-3 showed variable activity on the INSL3 receptor (LGR8/RXFP2) [PMID:16411781]. GtoPdb lists a full agonist, with no affinity value given [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor as curated; the mouse pair is projected from human evidence (ortholog inferred). Assay system details are not reported beyond the abstract.","localisation_and_range":"Ligand flagged as secreted and receptor as transmembrane [flag].","caveats":"Single paper read as abstract only; activity was weaker and less consistent than at RXFP1 or GPCR135 [PMID:16411781]. Direct binding to RXFP2 was not shown in the text we have.","key_references":[{"PMID":"16411781","why":"Reports variable relaxin-3 activity at LGR8/RXFP2"}],"covers":["LR001301","LR004699"]},"LR001310":{"pair":"RSPO1 -> LRP6","headline":"RSPO1 -> LRP6: only family-level abstract evidence of ectodomain interaction plus a UniProt regulation note.","interaction_type":"direct binding","direction_and_effect":"Cristin/R-spondin proteins physically interacted with the LRP6 and Fzd8 ectodomains in vivo and in vitro and activated TCF reporter and beta-catenin stabilisation [PMID:16543246]. UniProt describes RSPO1 acting through Kremen to block LRP6 internalization, not direct LRP6 binding [DB:UniProt].","molecular_requirements":"R-spondin did not form a ternary complex with both LRP6 and Fzd8 [PMID:16543246].","affinity_potency":[],"species_and_systems":"Mouse cristin/R-spondin proteins [PMID:16543246]; human pair ortholog-inferred.","localisation_and_range":"RSPO1 secreted per flag [flag].","caveats":"Abstract only; family-level not RSPO1-specific. Two abstract-insufficient papers. UniProt-cited work says RSpo1 does not directly activate LRP6 [DB:UniProt].","key_references":[{"PMID":"16543246","why":"R-spondin family binds LRP6 and Fzd8 ectodomains"}],"covers":["LR001310","LR004707"]},"LR003200":{"pair":"RTN4R -> ADGRB3","headline":"Direct nanomolar binding of RTN4R to BAI3 supported by one paper with full-text SPR data; the human pair is projected from other evidence.","interaction_type":"direct binding","direction_and_effect":"RTN4R ectodomain binds BAI3 (ADGRB3); BAI3-expressing cells aggregated specifically with RTN4R-expressing cells [PMID:34758294]. Signalling effect is not reported in our evidence for this pair.","molecular_requirements":"The single TSR2 domain of BAI3 bound RTN4Rs avidly and formed a complex with RTN4R by SEC [PMID:34758294]. EGTA did not reduce binding, so it is Ca2+ independent; C1ql3 did not compete with RTN4R for BAI binding [PMID:34758294].","affinity_potency":[{"value":"Kd = 1.9 nM","assay":"surface plasmon resonance, recombinant ectodomains (highest of the BAI-RTN4R pairs; BAI3-RTN4R)","system":"purified recombinant proteins","cite":"PMID:34758294"}],"species_and_systems":"Mouse C1ql3 and recombinant ectodomains, HEK 293F cell aggregation and SPR [PMID:34758294]. The human interaction is flagged as ortholog-inferred; a mouse pair is listed as not inferred. The curator row was originally recorded from the abstract only, but full-text excerpts are present.","localisation_and_range":"Trans-cellular adhesion complex, so contact-dependent [PMID:34758294]. ADGRB3 has no secreted flag in the dossier; RTN4R is not flagged secreted [flag].","caveats":"Only one paper. The crystal structure is of BAI1, not BAI3 [PMID:34758294]. The 1.9 nM Kd is reported as the BAI3-RTN4R value; species of the SPR proteins is not stated in the excerpts.","key_references":[{"PMID":"34758294","why":"SPR, cell aggregation and domain mapping for BAI3 and RTN4R"}],"covers":["LR003200","LR006420"]},"LR009389":{"pair":"SEMA4D -> ERBB2","headline":"No direct evidence: ERBB2 appears only as an associated partner of the SEMA4D-PLXNB1 receptor in Reactome.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified paper supports SEMA4D binding ERBB2. Reactome records a complex SEMA4D:ERBB2:p-Y-PLXNB1 and a reaction 'SEMA4D interacts with Plexin-B1:ErbB2' [DB:Reactome].","molecular_requirements":"ERBB2 appears to act together with PLXNB1, not as a ligand-binding receptor on its own; this is inferred from Reactome complex naming [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human (Reactome); experimental species not reported in our evidence.","localisation_and_range":"Not reported in our evidence beyond entity flags: SEMA4D flagged secreted and transmembrane [flag].","caveats":"No verified papers: outcome counts show 4 abstract_insufficient and 3 different_entity, none confirmed. Treat as a PLXNB1 co-receptor relationship rather than a direct pair.","key_references":[],"covers":["LR009389"]},"LR001400":{"pair":"SOST -> LRP6","headline":"Secreted sclerostin binds LRP6 (and LRP5) and antagonises canonical Wnt signalling; two abstract-level papers plus database records.","interaction_type":"direct binding","direction_and_effect":"Sclerostin antagonises canonical Wnt signalling and bound LRP5 as well as LRP6 [PMID:15778503]. SOST binds the LRP5/6 extracellular domain and disrupts Wnt-induced Frizzled-LRP complex formation [PMID:15908424]. Effect: antagonist/inhibitor.","molecular_requirements":"The binding site was mapped on LRP5 (first two YWTD-EGF repeat domains); canonical Wnt did not appear to compete with sclerostin for LRP5 binding [PMID:15778503]. Whether LRP6 uses the same domains is not reported in our evidence. LRP6 is a single-chain co-receptor [flag].","affinity_potency":[],"species_and_systems":"Human A293T and mouse MC3T3 cells [PMID:15778503]; Xenopus embryos and mammalian cells [PMID:15908424]. Mouse pair is ortholog-inferred. Database records: BioGRID Affinity Capture-Western [DB:BioGRID], IntAct pull down and bio-layer interferometry [DB:IntAct], structures [DB:PDB 3SOV] [DB:PDB 6L6R], Reactome SOST:LRP5/6 complex [DB:Reactome].","localisation_and_range":"SOST is flagged secreted and LRP6 as a transmembrane receptor [flag]; acts on cell-surface receptors.","caveats":"Both papers were read as abstracts only. Binding to LRP6 is stated alongside LRP5; LRP6-specific details are limited. No affinity values in our evidence.","key_references":[{"PMID":"15778503","why":"Sclerostin binds LRP5 and LRP6, antagonises Wnt"},{"PMID":"15908424","why":"SOST binds LRP5/6 ectodomain, disrupts Frizzled-LRP complex"}],"covers":["LR001400","LR004795"]},"LR002003":{"pair":"SPN -> SIGLEC1","headline":"CD43 is a T-cell counterreceptor for sialoadhesin (Siglec-1) from one abstract-level mouse paper.","interaction_type":"direct binding","direction_and_effect":"Sialoadhesin-Fc precipitated CD43 from murine T cells and CD43 expressed in COS cells supported increased binding to immobilised sialoadhesin [PMID:11238599]. CD43 is the counterreceptor; any signalling effect is not reported in our evidence.","molecular_requirements":"Binding was sialic acid dependent and abolished by the R97A mutation in sialoadhesin's membrane-distal Ig-like domain; both core-1 and core-2 O-linked CD43 glycoforms bound [PMID:11238599].","affinity_potency":[],"species_and_systems":"Mouse T cell line TK-1, COS and CHO cells [PMID:11238599]. IntAct solid phase assay record exists [DB:IntAct]. Human pair is ortholog-inferred.","localisation_and_range":"Both are membrane proteins, suggesting cell-cell contact interaction [flag].","caveats":"Abstract only; no affinity. Binding relies on glycosylation.","key_references":[{"PMID":"11238599","why":"CD43 identified as sialoadhesin counterreceptor"}],"covers":["LR002003","LR005331"]},"LR004799":{"pair":"SPP1 -> CD44","headline":"Osteopontin is a protein ligand of CD44 with direct-binding and functional support in mouse and human systems; CD44 acts mainly in chemotaxis and migration.","interaction_type":"direct binding","direction_and_effect":"Osteopontin was found to be a protein ligand of CD44 and induces chemotaxis [PMID:8560266]. The C-terminal domain of osteopontin acting on CD44 induces macrophage chemotaxis [PMID:12377945]. A phosphorylation-independent Eta-1/CD44 interaction inhibited IL-10 expression [PMID:10657301]. Recombinant human SPP1 recruited LX2 fibroblasts and promoted FAP+ fibroblast formation, reversed by siCD44 [PMID:39095854].","molecular_requirements":"CD44 binding does not need osteopontin serine phosphorylation, unlike integrin engagement [PMID:12377945]. Osteopontin amino termini interact with CD44 in a complement-regulation setting [PMID:11825898]. Co-receptor needs: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse macrophages [PMID:12377945][PMID:10657301]; human cells and recombinant human SPP1 on LX2 stellate cells with HCC conditioned medium and single-cell data [PMID:39095854]; human binding study [PMID:8560266].","localisation_and_range":"SPP1 is flagged secreted and not transmembrane [flag]; CD44 is flagged both secreted and transmembrane [flag]. Reactome records a SPP1:CD44 plasma-membrane complex [DB:Reactome].","caveats":"Four of five papers were read as abstracts only. The HCC paper is largely single-cell expression with siRNA validation, so it is indirect for binding [PMID:39095854]. PMID:11825898 has CD44 as a surface anchor for Factor H recruitment rather than signalling, and its mapping localises the CD44 interaction to different regions than PMID:12377945 (amino vs C-terminal), which the dossier does not reconcile.","key_references":[{"PMID":"8560266","why":"Osteopontin identified as a protein ligand of CD44"},{"PMID":"12377945","why":"Domain mapping: C-terminal osteopontin acts via CD44 to drive macrophage chemotaxis"},{"PMID":"39095854","why":"siCD44 reverses rhSPP1 effects on fibroblasts"}],"covers":["LR001404","LR004799"]},"LR006599":{"pair":"THY1 -> ITGB3","headline":"Thy-1 binds alphavbeta3 integrin (SPR, force spectroscopy); ITGB3 row inherits heterodimer evidence.","interaction_type":"direct binding","direction_and_effect":"Thy-1 and alphavbeta3 mediate bidirectional neuron-astrocyte communication, stimulating astrocyte migration and retraction of neuronal prolongations [PMID:29212879]; anti-Thy-1 antibodies blocked astrocyte stimulation but not cell binding [PMID:18346467].","molecular_requirements":"Both alphav and beta3 needed for neuron-astrocyte association; Thy-1 binds the alphavbeta3 heterodimer [PMID:18346467].","affinity_potency":[],"species_and_systems":"Optical tweezers [PMID:29212879]; DI TNC1 astrocytes, species unspecified [PMID:18346467].","localisation_and_range":"Membrane-bound trans contact between neuron and astrocyte [PMID:18346467].","caveats":"Abstract only; beta3 alone not tested separately; no affinity values.","key_references":[{"PMID":"18346467","why":"Thy-1/alphavbeta3 SPR and astrocyte signalling"},{"PMID":"29212879","why":"Force-dependent kinetics"}],"covers":["LR003398","LR006599"]},"LR002021":{"pair":"TIMD4 -> HAVCR1","headline":"TIM-4 reported as the ligand of TIM-1 (HAVCR1); costimulatory in T cells; evidence is functional, read from abstracts only.","interaction_type":"functional only","direction_and_effect":"TIM-4-Ig costimulated CD3/CD28-driven T-cell proliferation in vitro, and soluble TIM-1-Ig or TIM-4-Ig caused T-cell hyperproliferation in vivo, so TIM-4 on antigen-presenting cells is proposed as the endogenous TIM-1 ligand [PMID:15793576]. In allergic rhinitis, the TIM4/TIM1 interaction promoted CD4+ T-cell SIRT1 expression via PI3K/Akt phosphorylation and Th2 proliferation; silencing TIM4 in DCs or TIM1 in T cells reduced proliferation [PMID:28949386].","molecular_requirements":"not reported in our evidence. No complex partners reported.","affinity_potency":[],"species_and_systems":"The curated records list human experiments, but the allergic-rhinitis work (PMID 28949386) describes mice (OVA-pulsed splenic DCs, CD4+ T cells). The human pair is ortholog-inferred; the mouse pair is not [PMID:28949386].","localisation_and_range":"TIMD4 is flagged secreted and HAVCR1 as a receptor [flag]; the papers describe an APC-to-T-cell contact setting [PMID:15793576].","caveats":"Both papers were read as abstracts (the second with excerpts). No direct binding measurement (affinity, pull-down) is in the dossier; the first paper uses Ig fusion proteins in functional assays. Species labels in the curated rows conflict with the mouse model of PMID 28949386.","key_references":[{"PMID":"15793576","why":"Original report of TIM-4 as TIM-1 ligand, with costimulation assays"},{"PMID":"28949386","why":"TIM4/TIM1 signalling to SIRT1 in allergic mice"}],"covers":["LR002021","LR005349"]},"LR008498":{"pair":"TNFRSF4 -> TNFSF4","headline":"OX40 (CD134) and OX40L (CD134L): curated paper is an in vivo association study; binding itself comes from database structures.","interaction_type":"functional only","direction_and_effect":"In a rat small bowel transplant model, CD134 and CD134L were strongly expressed in acutely rejected allografts, and the paper concludes the CD134/CD134L interaction is associated with acute rejection [PMID:12134113]. The costimulatory signal is described as CD28-independent [PMID:12134113]. The pair is stored receptor-to-ligand.","molecular_requirements":"Not reported in our evidence beyond the pair itself.","affinity_potency":[],"species_and_systems":"Rat transplant model with mixed lymphocyte culture; the dossier lists species as unspecified [PMID:12134113]. Databases: IntAct X-ray crystallography [DB:IntAct], PDB 2HEV with chains of both proteins [DB:PDB 2HEV], and Reactome OX40L binds OX40 [DB:Reactome].","localisation_and_range":"TNFSF4 is flagged membrane-bound, not secreted [flag].","caveats":"The paper shows association with rejection and does not test binding; it was read as an abstract only [PMID:12134113]. Physical binding rests on database records.","key_references":[{"PMID":"12134113","why":"CD134/CD134L in rat small bowel allograft rejection"}],"covers":["LR008498"]},"LR004889":{"pair":"TNFSF13B -> TNFRSF13B","headline":"BAFF binds TACI with sub-nanomolar affinity; two abstract-only papers plus extensive database records.","interaction_type":"direct binding","direction_and_effect":"TACI binds BAFF (zTNF4) [PMID:10801128]; TACI expressed in HEK293T cells confers BAFF binding and TACI-Fc recognises soluble and membrane BAFF, with NF-kappaB signalling [PMID:10956646]. Soluble TACI-Ig inhibited proteinuria and prolonged survival in NZBWF1 lupus mice [PMID:10801128]. Annotated stimulatory [flag].","molecular_requirements":"Reactome lists a sBAFF,sAPRIL complex with 3xTACI and BCMA [DB:Reactome]; requirements not tested in our papers.","affinity_potency":[{"value":"subnanomolar affinity","assay":"BLyS binding to TACI expressed on cells (abstract wording, no exact value)","system":"HEK293T cells","cite":"PMID:10956646"}],"species_and_systems":"Human proteins [PMID:10956646]; TACI-Ig blockade in mice [PMID:10801128].","localisation_and_range":"BAFF flagged both secreted and transmembrane; TACI transmembrane [flag]. TACI-Fc recognised both cleaved soluble and membrane BAFF [PMID:10956646].","caveats":"Both papers read as abstract only. Also supported by BioGRID, IntAct and GtoPdb records [DB:BioGRID][DB:IntAct][DB:GtoPdb].","key_references":[{"PMID":"10956646","why":"Sub-nanomolar BLyS binding to TACI"},{"PMID":"10801128","why":"TACI and BCMA identified as BAFF receptors"}],"covers":["LR001498","LR004889"]},"LR004898":{"pair":"TNFSF15 -> TNFRSF25","headline":"TL1A is a ligand for DR3; one abstract-only paper with functional data plus databases.","interaction_type":"functional only","direction_and_effect":"TL1A is a ligand for DR3; it induces NF-kappaB activation and apoptosis in DR3-expressing cell lines, antagonised by TR6-Fc, and costimulates primary T cells, increasing IL-2 responsiveness and proinflammatory cytokine secretion in vitro and in vivo [PMID:11911831].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell lines and primary T cells; species not stated beyond annotation; abstract only [PMID:11911831].","localisation_and_range":"TNFSF15 flagged secreted and transmembrane; TNFRSF25 transmembrane [flag].","caveats":"Abstract only; TR6/DcR3 neutralises TL1A [PMID:11911831]. BioGRID, Reactome, UniProt, IntAct and GtoPdb records also exist [DB:BioGRID][DB:Reactome][DB:UniProt].","key_references":[{"PMID":"11911831","why":"TL1A is a DR3 ligand and costimulates T cells"}],"covers":["LR001508","LR004898"]},"LR008399":{"pair":"VTN -> SDC4","headline":"Vitronectin's basic domain is reported as a syndecan ligand; evidence is one abstract-only paper and is not specific to syndecan-4.","interaction_type":"functional only","direction_and_effect":"Vitronectin's 12 amino acid basic domain was identified as a syndecan binding site; ARH-77 cells transfected with syndecans -1, -2 or -4, but not Glypican-1, adhered to GST-VnHBD, and adhesion was lost when the basic domain was deleted [PMID:14681059].","molecular_requirements":"The basic domain, within the 40 amino acid heparin binding domain, is needed [PMID:14681059].","affinity_potency":[],"species_and_systems":"Human cells (HT-1080, dermal fibroblasts, transfected ARH-77) with recombinant baculoviral vitronectin [PMID:14681059].","localisation_and_range":"Vitronectin is deposited in the extracellular matrix [PMID:14681059]; the receptor has no localisation flags in our evidence.","caveats":"Abstract-only read. Syndecans -1 and -2 behaved like syndecan-4, and the curator notes that binding is heparan sulfate mediated and may not discriminate between family members [PMID:14681059]. The curated evidence sentence is only framing text.","key_references":[{"PMID":"14681059","why":"basic domain of vitronectin supports syndecan-expressing cell adhesion"}],"covers":["LR008399"]},"LR002030":{"pair":"WNT1 -> FZD10","headline":"FZD10 is reported as a WNT1 receptor in chick spinal cord, with a proximity-ligation interaction and LRP6-dependent signalling.","interaction_type":"direct binding","direction_and_effect":"In HEK293T cells FZD10 with LRP6 increased WNT1 signalling in an 8xSuperTopFlash assay, and proximity ligation showed an FZD10-WNT1 interaction [PMID:24599775].","molecular_requirements":"LRP6 co-expression was needed for FZD10 to promote WNT1 signalling; FZD10 alone with WNT1 inhibited signalling. PLA punctae formed with or without exogenous LRP6 [PMID:24599775].","affinity_potency":[],"species_and_systems":"Chick embryo spinal cord expression; reporter assay in HEK293T and PLA in transfected COS7 cells [PMID:24599775]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence.","caveats":"Interaction shown by proximity within 40 nm, not purified-protein binding. Overexpressed FZD10 alone inhibited WNT1 signalling [PMID:24599775].","key_references":[{"PMID":"24599775","why":"FZD10 as WNT1 receptor: PLA and LRP6-dependent reporter"}],"covers":["LR002030","LR005356"]},"LR007499":{"pair":"WNT11 -> FZD7:LRP5","headline":"WNT11 to FZD7:LRP5 is inferred from a FZD7-only paper; the co-receptor was not tested.","interaction_type":"functional only","direction_and_effect":"A colorectal cancer paper reports Wnt11 directly interacts with FZD7 to activate PCP/ROCK signalling [PMID:42760160].","molecular_requirements":"Evidence concerns FZD7 alone; the contribution of LRP5 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human colorectal cancer cells, abstract read only [PMID:42760160].","localisation_and_range":"Ligand is flagged secreted [flag]; Reactome lists a generic WNT:FZD plasma-membrane complex [DB:Reactome].","caveats":"The LRP5 chain is unsupported; complex scoring would rely on FZD7 evidence only. One review-only and two abstract_insufficient rows.","key_references":[{"PMID":"42760160","why":"Wnt11-FZD7 interaction in CRC (FZD7 only)"}],"covers":["LR007499"]},"LR006689":{"pair":"WNT3A -> APP","headline":"One abstract-level paper reports APP binds Wnt3a via its cysteine-rich domain, promoting APP stability; thin support.","interaction_type":"direct binding","direction_and_effect":"Wnt3a binding promotes full-length APP recycling and stability, in contrast to Wnt5a, which promotes lysosomal targeting [PMID:34515635]. APP is therefore treated as a Wnt receptor whose levels Wnt3a raises (agonist label from curators).","molecular_requirements":"A conserved cysteine-rich domain in the APP extracellular region is required for Wnt binding; deleting it abrogates Wnt effects on full-length APP [PMID:34515635]. Co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human APP constructs, mouse embryonic primary cortical neurons and HEK293T cells; Drosophila APPL used for the Wnt5 work [PMID:34515635]. Both human and mouse interactions are ortholog-inferred.","localisation_and_range":"APP is flagged secreted, receptor and transmembrane [flag]; WNT3A is flagged secreted [flag].","caveats":"The full-text excerpts shown in our evidence document co-IP with Wnt5a, not Wnt3a; the Wnt3a binding claim rests on the abstract. No affinity reported. The readout is APP trafficking, not classical downstream signalling.","key_references":[{"PMID":"34515635","why":"APP binds Wnt3a and Wnt5a via its CRD; Wnt3a stabilises APP"}],"covers":["LR003489","LR006689"]},"LR004979":{"pair":"WNT3A -> FZD8","headline":"WNT3A binds FZD8 directly in several purified and cell-based binding studies.","interaction_type":"direct binding","direction_and_effect":"Purified mouse Fz8 CRD and human LRP6 ectodomain inhibited Wnt/beta-catenin signaling, and the Fz8 CRD.Wnt3a.LRP6 complex was reconstituted in vitro [PMID:20093360]. WNT-3A showed strong binding (++++, KD < 10 nm) to FZD4/5/7/8 CRDs [PMID:25605717]. WNT3A bound sFZD8-Fc [PMID:30304675].","molecular_requirements":"Wnt3a binds a region of LRP6 comprising the third and fourth beta-propeller domains, and a Fz8 CRD.Wnt3a.LRP6 complex forms [PMID:20093360]. Whether FZD8 alone suffices is not reported in our evidence.","affinity_potency":[{"value":"KD < 10 nm","assay":"Bio-layer interferometry, purified WNT-3A on FZD CRD-Fc, FZD4/5/7/8 grouped","system":"purified proteins","cite":"PMID:25605717"}],"species_and_systems":"Mouse Fz8 CRD with human LRP6 [PMID:20093360]; mouse per curation [PMID:25605717]; human, HEK293 cells [PMID:30304675]. Human and mouse versions are listed.","localisation_and_range":"WNT3A carries a secreted flag and no transmembrane flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"PMID:20093360 was read as abstract only and affinity values are not in our excerpt. The PMID:25605717 quote is flagged as browser-read, unverifiable. The KD bound covers several FZDs. In PMID:30304675 FZD8 binding was a positive control.","key_references":[{"PMID":"20093360","why":"Reconstituted Fz8 CRD.Wnt3a.LRP6 complex from purified proteins"},{"PMID":"25605717","why":"Bio-layer interferometry of WNT-3A and FZD CRDs"},{"PMID":"30304675","why":"WNT3A bound sFZD8-Fc in HEK293 cell studies"}],"covers":["LR001590","LR004979"]},"LR004988":{"pair":"WNT4 -> FZD2","headline":"WNT4 binds FZD2 directly but does not activate canonical signalling in 32D cells; a co-IP in MC3T3 cells also found Wnt4-Fzd2.","interaction_type":"direct binding","direction_and_effect":"Bio-layer interferometry shows WNT-4 binds the FZD2 CRD, but did not activate the WNT-beta-catenin pathway through FZD2 [PMID:25605717]. DVL isoform effects suggest non-canonical output.","molecular_requirements":"CRD binding suffices in the assay [PMID:25605717]. Wnt4-LRP5, Wnt4-LRP6 and Wnt4-Fzd2 complexes also found [PMID:31216173].","affinity_potency":[],"species_and_systems":"32D cells, human labelled [PMID:25605717]; co-IP in MC3T3 (mouse) cells [PMID:31216173]. Human pair ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Abstract-only for 25605717; 31216173 browser-read and not spot-checked. Affinity values not in our evidence. The 'agonist' label conflicts with non-activation of canonical signalling.","key_references":[{"PMID":"25605717","why":"BLI binding of WNT-4 to FZD2 CRD"},{"PMID":"31216173","why":"Wnt4-Fzd2 co-IP"}],"covers":["LR001599","LR004988"]},"LR006698":{"pair":"WNT4 -> FZD4","headline":"WNT4 binds FZD4 in purified protein and co-IP assays but does not activate canonical beta-catenin signalling through it.","interaction_type":"direct binding","direction_and_effect":"Bio-layer interferometry shows WNT-4 directly binds the FZD4 cysteine-rich domain, but in 32D cells WNT-4 did not activate the WNT-beta-catenin pathway through it; effects on DVL2 vs DVL3 phosphorylation suggest non-canonical output [PMID:25605717].","molecular_requirements":"The CRD of the Frizzled is sufficient for binding in the assay [PMID:25605717].","affinity_potency":[],"species_and_systems":"Bio-layer interferometry and 32D cells, human labelled [PMID:25605717]. Mouse version listed directly; human is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Abstract only; affinity values are in a table not shown in our evidence. Curator effect label 'agonist' conflicts with the non-activation of canonical signalling.","key_references":[{"PMID":"25605717","why":"WNT-FZD CRD binding kinetics and signalling"}],"covers":["LR003498","LR006698"]},"LR007688":{"pair":"WNT5A -> FZD7:LRP5","headline":"Database-asserted only: no curator-verified paper; support is IntAct and Reactome records for WNT5A with FZD7 and LRP5.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. Reactome records a WNT5A:FZD7 complex and a binding reaction in which WNT5 binds FZD7 [DB:Reactome R-HSA-9673349].","molecular_requirements":"The records name FZD7 binding (Reactome) and a WNT5A-LRP5 association (IntAct, comigration, tandem affinity purification and co-immunoprecipitation) [DB:IntAct O75084-P41221]. A single ternary FZD7:LRP5 complex is not shown in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species and cell systems not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted and LRP5 transmembrane [flag]; range not otherwise reported.","caveats":"No papers were verified (one review-only row). The complex pairing appears to combine separate binary records, so CCC scoring by least-expressed subunit rests on database assertion only.","key_references":[],"covers":["LR007688"]},"LR004997":{"pair":"WNT5A -> LRP5","headline":"Functional support that LRP5 acts as a co-receptor with a Frizzled for WNT5A activation of beta-catenin signalling; no direct binding shown.","interaction_type":"functional only","direction_and_effect":"With mFz4, LRP5 coexpression lets Wnt5a protein activate the STF luciferase reporter in 293Fz4 cells; without LRP5 it does not [PMID:16602827]. In human endometrial stem-like cells, DKK1 reduced WNT5A binding and the WNT5A-induced increase in active beta-catenin [PMID:35295855].","molecular_requirements":"Requires a Frizzled partner: Fz4 [PMID:16602827] or FZD5 [PMID:35295855]. LRP6 did not substitute in 293Fz4 cells [PMID:16602827].","affinity_potency":[],"species_and_systems":"293 and 293Fz4 cells with mouse Fz4 [PMID:16602827]; human endometrial mesenchymal stem-like cells, plus mouse endometrial staining [PMID:35295855].","localisation_and_range":"Ligand flagged secreted, LRP5 transmembrane [flag].","caveats":"No direct binding assay. DKK1 inhibits LRP5 and LRP6, so specificity to LRP5 is indirect [PMID:35295855]. LRP6 data in 293Fz4 cells are 'unpublished data' in the paper [PMID:16602827]. The same paper shows Wnt5a inhibiting canonical signalling in other receptor contexts.","key_references":[{"PMID":"16602827","why":"Wnt5a activates TCF signalling with Fz4 plus LRP5"},{"PMID":"35295855","why":"WNT5A with FZD5 and LRP5 in endometrial stem-like cells"}],"covers":["LR001608","LR004997"]},"LR005000":{"pair":"WNT5A -> ROR2","headline":"Well supported: WNT5A binds the ROR2 CRD, with structural, binding and signalling data across several papers.","interaction_type":"direct binding","direction_and_effect":"Wnt5a binds the CRD of Ror2 in vitro [PMID:12839624]. Loss of ROR1/ROR2 decreased WNT5A signalling in MEFs and was rescued by wild-type ROR2 [PMID:38780011]. Curated stimulatory. Purified Wnt5a also inhibited Wnt3a canonical signalling via Ror2 [PMID:16602827].","molecular_requirements":"The ROR2 CRD is required and minimally sufficient; it lacks the hydrophobic pocket seen in other CRDs [PMID:38780011]. Wnt5a coprecipitated with Ror2 but not LRP6 [PMID:18606138]. ROR KO cells retained some WNT5A signalling, indicating additional receptors [PMID:38780011]. Frizzled involvement was suggested by antibody experiments [PMID:38780011].","affinity_potency":[],"species_and_systems":"Recombinant proteins, MEFs, Xenopus and mouse knockouts; WNT5A-SFRP2 complex bound ROR2-ECD in co-IP [PMID:39229119, preprint].","localisation_and_range":"Reactome lists a WNT5A:ROR2:VANGL2 plasma-membrane complex [DB:Reactome R-HSA-4551543]. ROR2 flagged transmembrane [flag].","caveats":"No affinity value reported. Several papers were abstract-only; PMID 39229119 is a bioRxiv preprint whose evidence sentence concerns WNT2B and only mentions WNT5A-SFRP2 as comparison.","key_references":[{"PMID":"12839624","why":"In vitro binding of Wnt5a to the Ror2 CRD"},{"PMID":"38780011","why":"ROR2 CRD structure and requirement for WNT5A signalling"},{"PMID":"18606138","why":"Wnt5a co-IP with Ror2 not LRP6"}],"covers":["LR001611","LR005000"]},"LR008777":{"pair":"FST -> BMPR2","headline":"No curator-verified paper; support is a single BioGRID co-crystal structure record.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"BioGRID lists a co-crystal structure for FST-BMPR2 [DB:BioGRID]; subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair; experimental system not reported beyond the structure record [DB:BioGRID].","localisation_and_range":"Not reported in our evidence.","caveats":"No judged papers; one review-only and three abstract-insufficient papers were set aside. The pair rests on one BioGRID record (PMID 16198295) [DB:BioGRID].","key_references":[{"PMID":"16198295","why":"Source cited by the BioGRID co-crystal structure record"}],"covers":["LR008777"]},"LR002012":{"pair":"SPX -> GALR3","headline":"Spexin is an agonist of GALR3, supported by receptor activation assays and an adipocyte study.","interaction_type":"functional only","direction_and_effect":"Agonist. SPX activated human, Xenopus and zebrafish GALR2/3 family receptors but not GALR1, and showed much higher potency at GALR3 than galanin [PMID:24517231]. In adipocytes, SPX effects were mediated via GALR2 and GALR3 [PMID:30305242]. GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"Single receptor. In adipocytes both GALR2 and GALR3 were implicated [PMID:30305242]. Subunit needs are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Receptor activation across human, Xenopus and zebrafish receptors [PMID:24517231]; murine 3T3-L1 cells and human adipocytes [PMID:30305242]. Mouse pair is listed separately.","localisation_and_range":"SPX is annotated secreted and GALR3 transmembrane [flag]; paracrine or endocrine.","caveats":"Both papers abstract only. No assay of direct binding is shown; the potency number is not quoted. The adipocyte study cannot separate GALR2 from GALR3. UniProt names SPX as a GALR2/GALR3 ligand [DB:UniProt].","key_references":[{"PMID":"24517231","why":"SPX activates GALR2/3, more potent than galanin at GALR3."},{"PMID":"30305242","why":"SPX effects in adipocytes mediated via GALR2 and GALR3."}],"covers":["LR002012","LR005340"]}};